Object.assign(window.TEM8_DICTIONARY, {"build":{"media":{"uk":"media/uk/build__gb_1.mp3","us":"media/us/build__us_1.mp3"},"oxford":{"phon":"bɪld","pos":"verb","senses":[{"en":"to make something, especially a building, by putting parts together","cn":"建筑；建造","g":"[transitive, intransitive]","ex":{"en":"They have permission to build 200 new homes.","cn":"他们得到建 200 座新房的许可。"}},{"en":"to create or develop something","cn":"创建；开发；发展","g":"[transitive]","ex":{"en":"They are trying to build long-term relationships.","cn":"他们正试图建立长期关系。"}},{"en":"to become gradually stronger","cn":"逐渐增强","g":"[intransitive]","ex":{"en":"The tension and excitement built gradually all day.","cn":"整个一天中，紧张与兴奋的气氛越来越浓。"}},{"en":"the shape and size of the human body","cn":"体形；体格；身材","g":"[uncountable, countable, usually singular]","ex":{"en":"He was described as a man of average build.","cn":"他被描述为一个中等身材的人。"},"pos":"noun"},{"en":"the process of building or constructing something","cn":"建造；建设","g":"[singular]","ex":{"en":"We are just completing the build of our new house.","cn":"眼下我们正在完成我们新房子的建造工作。"},"pos":"noun"},{"en":"a version of a piece of software that is created, especially one of a series of versions created before the final version is released","cn":"（软件开发过程中的）构建版本","g":"[countable]","ex":{"en":"You can sign up to help them test the alpha build of the game.","cn":"您可以注册帮助他们测试游戏的 Alpha 版本。"},"pos":"noun"},{"en":"the form or style in which something is constructed, especially a vehicle","cn":"（尤指汽车的）做工","g":"[singular]","ex":{"en":"a car with superb build quality","cn":"质量一流的一款汽车"},"pos":"noun"},{"en":"the way in which something, especially a story or film, develops towards the most exciting or important point","cn":"创建；开发","g":"[singular]","ex":{"en":"the slow build of the plot","cn":"情节的缓慢发展"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"建筑；建造","en":"If you build something, you make it by joining things together.","ex":{"en":"Developers are now proposing to build a hotel on the site","cn":"开发商现在建议在这个地方盖一座宾馆。"}},{"pos":"VERB 动词","cn":"把…建入；把…嵌入","en":"If you build something into a wall or object, you make it in such a way that it is in the wall or object, or is part of it.","ex":{"en":"If the TV was built into the ceiling, you could lie there while watching your favourite programme.","cn":"如果把电视嵌入天花板，你就可以躺在那里欣赏你最喜欢的节目了。"}},{"pos":"VERB 动词","cn":"创建；建立","en":"If people build an organization, a society, or a relationship, they gradually form it.","ex":{"en":"He and a partner set up on their own and built a successful fashion company","cn":"他和同伴自己创业，创办了一家成功的时装公司。"}},{"pos":"VERB 动词","cn":"把（组织、系统或产品）建立于","en":"If you build an organization, system, or product on something, you base it on it.","ex":{"en":"We will then have a firmer foundation of fact on which to build theories","cn":"那样我们将会获得一个建立理论所需的更为牢固的事实基础。"}},{"pos":"VERB 动词","cn":"使成为（政策、系统或产品的）组成部分","en":"If you build something into a policy, system, or product, you make it part of it.","ex":{"en":"We have to build computers into the school curriculum","cn":"我们必须把计算机纳入到学校的课程中。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（信心或信任）逐渐增强","en":"To build someone's confidence or trust means to increase it gradually. If someone's confidence or trust builds, it increases gradually.","ex":{"en":"The encouragement that young boys receive builds a greater self-confidence","cn":"小男孩受到的鼓励会增强他们的自信心。"}},{"pos":"VERB 动词","cn":"（在…的基础上）继续发展","en":"If you build on the success of something, you take advantage of this success in order to make further progress.","ex":{"en":"Build on the qualities you are satisfied with and work to change those you are unhappy with","cn":"以自己满意的优点为发展基础，努力改变自己不满意的地方。"}},{"pos":"VERB 动词","cn":"（压力、速度、声音或激情）逐渐变大，逐渐增强","en":"If pressure, speed, sound, or excitement builds, it gradually becomes greater.","ex":{"en":"Pressure built yesterday for postponement of the ceremony","cn":"要求推迟仪式的压力昨天进一步增大。"}},{"pos":"N-VAR 可变名词","cn":"体形；体格；身材","en":"Someone's build is the shape that their bones and muscles give to their body.","ex":{"en":"He's described as around thirty years old, six feet tall and of medium build","cn":"他被描述成一个30岁左右、6英尺高、中等身材的人。"}},{"pos":"","cn":"","en":"相关词组：build up build up to"}]},"examples":[{"en":"All the pressure built up and he was off work for weeks with stress.","cn":"各方面的压力越来越大，他因负荷太重有好几个星期没上班。"},{"en":"This information will help us build a picture of his attacker.","cn":"这条信息将有助于描画出袭击他的人的相貌。"}]},"button":{"media":{"img":["media/pic/fasteners_clothes_comp.jpg","media/thumb/button.jpg"],"uk":"media/uk/button__gb_1.mp3","us":"media/us/button__us_1.mp3"},"oxford":{"phon":"ˈbʌtn","pos":"noun","senses":[{"en":"a small round piece of metal, plastic, etc. that is sewn onto a piece of clothing and used for fastening two parts together","cn":"纽扣；扣子","lab":"British English","ex":{"en":"to do up/undo your buttons","cn":"系上／解开扣子"}},{"en":"a small part of a machine that you press to make it work","cn":"（机器的）按钮","ex":{"en":"the start/stop/pause button","cn":"开始/停止/暂停按钮"}},{"en":"a small area on a computer screen that you click on to make it do something","cn":"（电脑屏幕上的）按键","ex":{"en":"Click on the back button to go back to the previous screen.","cn":"点击返回键，回到上一页。"}},{"en":"a badge, especially one with a message printed on it","cn":"（尤指印有信息的）徽章","lab":"especially North American English","ex":{"en":"He wore a button saying ‘Life begins at 40!’","cn":"他戴着一枚纽扣，上面写着“人生从 40 岁开始！”"}},{"en":"to fasten something with buttons; to fasten the buttons on a piece of clothing somebody is wearing","cn":"用扣子系紧；扣上扣子","g":"[transitive]","ex":{"en":"She hurriedly buttoned (up) her blouse.","cn":"她急忙扣好衬衫。"},"pos":"verb"},{"en":"to be fastened with buttons","cn":"用纽扣扣上","g":"[intransitive]","ex":{"en":"The dress buttons (up) at the back.","cn":"这件连衣裙是从后背系扣的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纽扣；扣子","en":"Buttons are small hard objects sewn on to shirts, coats, or other pieces of clothing. You fasten the clothing by pushing the buttons through holes called buttonholes.","ex":{"en":"...a coat with brass buttons.","cn":"带铜纽扣的外套"}},{"pos":"VERB 动词","cn":"扣上…的纽扣","en":"If you button a shirt, coat, or other piece of clothing, you fasten it by pushing its buttons through the buttonholes.","ex":{"en":"Ferguson stood up and buttoned his coat.","cn":"弗格森站起身来，扣上了外套。"}},{"pos":"N-COUNT 可数名词","cn":"（机器的）按钮，开关","en":"A button is a small object on a machine or electrical device that you press in order to operate it.","ex":{"en":"He reached for the remote control and pressed the 'play' button.","cn":"他伸手拿过遥控器，按下“播放”键。"}},{"pos":"N-COUNT 可数名词","cn":"圆形小徽章","en":"A button is a small piece of metal or plastic which you wear in order to show that you support a particular movement, organization, or person. You fasten a button to your clothes with a pin."},{"pos":"PHRASE 短语","cn":"（巧妙地）获取想要的东西","en":"If you say that someone presses the right button or pushes the right button, you mean that they get what they want from a particular situation or person by behaving in a clever way.","ex":{"en":"Buchanan pushed all the right buttons, appealing to Maher's loyalty and to his guilt.","cn":"布坎南通过激发马厄的忠心和负罪感得到了他想要的东西。"}},{"pos":"","cn":"","en":"相关词组：button up"}]},"examples":[{"en":"Choose ‘printer’ from the menu and click with the right mouse button.","cn":"从选单上选取“打印机”，然后点击鼠标右键。"},{"en":"I've known him for years, but I still don't know what pushes his buttons.","cn":"我已认识他多年，可还是摸不透他的脾气。"}]},"but":{"media":{"uk":"media/uk/but__gb_1.mp3","us":"media/us/but__us_1.mp3"},"oxford":{"phon":"bət","pos":"conjunction","senses":[{"en":"used to introduce a word or phrase that contrasts with what was said before","cn":"而；相反","ex":{"en":"I got it wrong. It wasn't the red one but the blue one.","cn":"我弄错了。不是红的那个，是蓝的那个。"}},{"en":"however; despite this","cn":"然而；尽管如此","ex":{"en":"I'd asked everybody but only two people came.","cn":"每个人我都请了，却只来了两个人。"}},{"en":"used when you are saying sorry about something","cn":"（表示歉意时说）","ex":{"en":"I'm sorry but I can't stay any longer.","cn":"很抱歉，我不能再待下去了。"}},{"en":"used to introduce a statement that shows that you are surprised or annoyed, or that you disagree","cn":"（引出下文，表示吃惊、生气或不同意）","ex":{"en":"But that's not possible!","cn":"但那是不可能的！"}},{"en":"except","cn":"除…外；只有","ex":{"en":"I had no choice but to sign the contract.","cn":"我别无选择，只好签了合同。"}},{"en":"used before repeating a word in order to emphasize it","cn":"（重复字词前用，加强语气）","ex":{"en":"Nothing, but nothing would make him change his mind.","cn":"没有什么，绝对没有什么会使他改变主意。"}},{"en":"used to emphasize that something is always true","cn":"（强调一贯真实）","lab":"literary","ex":{"en":"She never passed her old home but she thought of the happy years she had spent there (= she always thought of them).","cn":"她每次经过自己的旧居，都会想起在那里度过的幸福岁月。"}},{"en":"except; apart from","cn":"除了；除…之外","ex":{"en":"We've had nothing but trouble with this car.","cn":"我们这辆车净出毛病。"},"pos":"preposition"},{"en":"only","cn":"仅仅；只有","ex":{"en":"I don't think we'll manage it. Still, we can but try.","cn":"我想我们应付不了这事。但不妨试试。"},"pos":"adverb"},{"en":"a reason that somebody gives for not doing something or not agreeing","cn":"借口；托辞","ex":{"en":"‘Let us have no buts,’ he said firmly. ‘You are coming.’","cn":"“别找借口了。”他坚定地说，“你得来。”"},"pos":"noun"}]},"collins":{"senses":[{"pos":"CONJ-COORD 连词","cn":"可是；但是；然而","en":"You use but to introduce something which contrasts with what you have just said, or to introduce something which adds to what you have just said.","ex":{"en":"'You said you'd stay till tomorrow.' — 'I know, Bel, but I think I would rather go back.'","cn":"“你说过你要呆到明天的。”——“我知道，贝尔，但我还是想回去。”"}},{"pos":"CONJ-COORD 连词","cn":"但是；不过","en":"You use but when you are about to add something further in a discussion or to change the subject.","ex":{"en":"They need to recruit more people into the prison service. But another point I'd like to make is that many prisons were built in the nineteenth century.","cn":"监狱需要招募更多的工作人员。但我想补充一点，很多监狱都是在19世纪建造的。"}},{"pos":"CONJ-COORD 连词","cn":"（用于表示歉意）但是","en":"You use but after you have made an excuse or apologized for what you are just about to say.","ex":{"en":"Please excuse me, but there is something I must say","cn":"不好意思，但有些话我必须说。"}},{"pos":"CONJ-COORD 连词","cn":"（引出下文，表示惊讶、难以置信、拒绝或抗议）但是，可是","en":"You use but to introduce a reply to someone when you want to indicate surprise, disbelief, refusal, or protest.","ex":{"en":"'I don't think I should stay in this house' — 'But why?'","cn":"“我觉得我不应该再呆在这所房子里。”——“可是为什么？”"}},{"pos":"PREP 介词","cn":"除了","en":"But is used to mean 'except'.","ex":{"en":"Europe will be represented in all but two of the seven races","cn":"除了两项赛事之外，欧洲在其余5项赛事中都有代表参加。"}},{"pos":"ADV 副词","cn":"仅仅;只;才","en":"But is used to mean 'only'.","ex":{"en":"This is but one of the methods used to try and get alcoholics to give up drink.","cn":"这只是为让那些酗酒者戒酒所尝试的方法之一。"}},{"pos":"N-PLURAL 复数名词","cn":"借口；托词","en":"You use buts in expressions like 'no buts' and 'ifs and buts' to refer to reasons someone gives for not doing something, especially when you do not think that they are good reasons.","ex":{"en":"'B-b-b-b-but' I stuttered. — 'Never mind the buts,' she ranted","cn":"“但——但——但是”，我结结巴巴地说道。——“别跟我讲那些‘但是’了。”她咆哮道。"}},{"pos":"PHRASE 短语","cn":"不得不；非…不可；必然","en":"You use cannot but ,could not but, and cannot help but when you want to emphasize that you believe something must be true and that there is no possibility of anything else being the case.","ex":{"en":"The pistol was positioned where I couldn't help but see it","cn":"手枪放在我抬眼就能看见的地方。"}},{"pos":"PHRASE 短语","cn":"倘没有；要不是","en":"You use but for to introduce the only factor that causes a particular thing not to happen or not to be completely true.","ex":{"en":"...the small square below, empty but for a delivery van and a clump of palm trees","cn":"下面的小广场空空荡荡,只有一辆送货车和几棵棕榈树"}},{"pos":"PHRASE 短语","cn":"（表示与前面说过的话略有矛盾）不过，然而","en":"You use but then or but then again before a remark which slightly contradicts what you have just said.","ex":{"en":"My husband spends hours in the bathroom, but then again so do I.","cn":"我丈夫常占用浴室好几个小时，不过我也是这样。"}},{"pos":"PHRASE 短语","cn":"（表示前述事情并不奇怪）不过，但是","en":"You use but then before a remark which suggests that what you have just said should not be regarded as surprising.","ex":{"en":"He was a fine young man, but then so had his father been","cn":"他年轻有为，不过他父亲也曾经是。"}},{"pos":"","cn":"","en":"all but→see: ; anything but→see: ;"}]},"examples":[{"en":"There were a lot of famous people there: Tom Hanks and Julia Roberts, to name but two.","cn":"那里有很多名人：只提两个名字吧，有汤姆 · 汉克斯和朱莉娅 · 罗伯茨。"},{"en":"‘Here's the money I owe you.’ ‘But that's not right — it was only £10.’ “","cn":"这是我欠你的钱。” “但这不对呀，我只借了 10 英镑给你。”"}]},"burns":{"lemma":"burn"},"bucket":{"oxford":{"phon":"ˈbʌkɪt","pos":"noun","senses":[{"en":"an open container with a handle, used for carrying or holding liquids, sand, etc.","cn":"（有提梁的）桶","g":"[countable]","lab":"British English","ex":{"en":"a plastic bucket","cn":"塑料桶"}},{"en":"a large container that is part of a crane or digger and is used for lifting things","cn":"吊桶；水斗；（挖掘机的）铲斗","g":"[countable]"},{"en":"the amount contained in a bucket","cn":"一桶（的量）","g":"[countable]","ex":{"en":"two buckets/bucketfuls of water","cn":"两桶水"}},{"en":"a large amount","cn":"大量","g":"[plural]","lab":"informal","ex":{"en":"To succeed in show business, you need buckets of confidence.","cn":"要想在演艺界干出名堂，就得有十足的信心。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（有提手的）桶，吊桶，水桶","en":"A bucket is a round metal or plastic container with a handle attached to its sides. Buckets are often used for holding and carrying water.","ex":{"en":"We drew water in a bucket from the well outside the door","cn":"我们用一个吊桶从门外的井中打水。"}},{"pos":"QUANT 数量词","cn":"大量","en":"Buckets or bucket-loads of something means a large amount of it.","ex":{"en":"They obviously have buckets of confidence","cn":"很明显，他们信心十足。"}},{"pos":"N-PLURAL 复数名词","cn":"（涕泪）滂沱；（大雨）瓢泼","en":"If someone cries buckets, they cry a lot because they are very upset. If it rains buckets, it rains a lot.","ex":{"en":"He was weeping buckets","cn":"他正哭得稀里哗啦的。"}},{"pos":"PHRASE 短语","cn":"蹬腿儿；咽气儿","en":"If you say that someone has kicked the bucket, you mean that they have died."},{"pos":"","cn":"","en":"相关词组：bucket down"}]},"media":{"img":["media/ldoce/img/bucket.jpg","media/pic/cleaning_comp.jpg"],"uk":"media/uk/bucket__gb_1.mp3","us":"media/us/bucket__us_1.mp3"},"examples":[{"en":"To succeed in show business, you need buckets of confidence.","cn":"要想在演艺界干出名堂，就得有十足的信心。"},{"en":"( BrE ) They were playing on the beach with their buckets and spades.","cn":"他们带着桶和铲子在沙滩上玩。"}]},"burnt":{"oxford":{"phon":"bɜːnt","pos":"adjective","senses":[{"en":"damaged or injured by burning","cn":"烧坏的；烧伤的；烫伤的；灼伤的","ex":{"en":"burnt toast","cn":"烤焦了的面包片"}}]},"media":{"uk":"media/uk/burnt__gb_2.mp3","us":"media/us/burnt__us_2.mp3"},"examples":[{"en":"Your hand looks badly burnt.","cn":"你的手似乎烧伤很重。"},{"en":"burnt toast","cn":"烤焦了的面包片"}],"collins":{"senses":[{"pos":"","cn":"","en":"Burnt is a past tense and past participle of burn."}]}},"buzz":{"media":{"uk":"media/uk/buzz__gb_1.mp3","us":"media/us/buzz__us_1.mp3"},"oxford":{"phon":"bʌz","pos":"verb","senses":[{"en":"to make a continuous low sound","cn":"发出嗡嗡声","g":"[intransitive]","ex":{"en":"Bees buzzed lazily among the flowers.","cn":"蜜蜂在花丛中懒洋洋地嗡嗡作响。"}},{"en":"to make a sound like a bee buzzing","cn":"发出蜂鸣声","g":"[intransitive]","ex":{"en":"The doorbell buzzed loudly.","cn":"门铃蜂鸣声大作。"}},{"en":"to be full of excitement, activity, etc.","cn":"充满兴奋（或活动等）","g":"[intransitive]","ex":{"en":"New York buzzes from dawn to dusk.","cn":"纽约从早到晚都熙熙攘攘的。"}},{"en":"to call somebody to come by pressing a buzzer","cn":"用蜂鸣器（发信号）","g":"[intransitive, transitive]","ex":{"en":"The doctor buzzed for the next patient to come in.","cn":"医生按蜂鸣器叫下一个病人进来。"}},{"en":"to fly very close to somebody/something, especially as a warning or threat","cn":"飞近（尤指作为警告或威胁）","g":"[transitive]","lab":"informal"},{"en":"a continuous sound like the one that a bee, a buzzer or other electronic device makes","cn":"嗡嗡声；蜂鸣声","g":"[countable, usually singular]","ex":{"en":"The air was alive with the buzz of bees and dragonflies.","cn":"空中有蜜蜂和蜻蜓的嗡嗡声，生气勃勃。"},"pos":"noun"},{"en":"the sound of people talking, especially in an excited way","cn":"唧唧喳喳的谈话声","g":"[singular]","ex":{"en":"The buzz of conversation suddenly stopped when she came into the room.","cn":"她一踏进屋子里，热烈的谈话便戛然而止。"},"pos":"noun"},{"en":"a strong feeling of pleasure, excitement or achievement","cn":"（愉快、兴奋或成就的）强烈情感","g":"[singular, uncountable]","lab":"informal","ex":{"en":"a buzz of excitement/expectation","cn":"十分兴奋／期待"},"pos":"noun"},{"en":"news that people tell each other that may or may not be true","cn":"传闻；传言","g":"[singular]","lab":"informal","ex":{"en":"The buzz is that Matt is in Scotland. Have you heard anything?","cn":"传言说马特在苏格兰。你听到什么了吗？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"发出嗡嗡声","en":"If something buzzes or buzzes somewhere, it makes a long continuous sound, like the noise a bee makes when it is flying.","ex":{"en":"The intercom buzzed and he pressed down the appropriate switch","cn":"对讲机发出嗡嗡声，他按下了相应的开关。"}},{"pos":"VERB 动词","cn":"匆忙地走动；忙得团团转","en":"If people are buzzing around, they are moving around quickly and busily.","ex":{"en":"A few tourists were buzzing about","cn":"几个观光客在匆匆游览。"}},{"pos":"VERB 动词","cn":"（想法）在脑海中萦绕，翻腾","en":"If questions or ideas are buzzing around your head, or if your head is buzzing with questions or ideas, you are thinking about a lot of things, often in a confused way.","ex":{"en":"Many more questions were buzzing around in my head","cn":"还有很多问题在我的脑海里翻腾。"}},{"pos":"VERB 动词","cn":"充满嘈杂的（谈话、活动）声","en":"If a place is buzzing with activity or conversation, there is a lot of activity or conversation there, especially because something important or exciting is about to happen.","ex":{"en":"The rehearsal studio is buzzing with lunchtime activity.","cn":"大家在吃午饭，排练室里很是嘈杂。"}},{"pos":"N-SING 单数名词","cn":"嗡嗡的说话声","en":"You can use buzz to refer to a long continuous sound, usually caused by lots of people talking at once.","ex":{"en":"A buzz of excitement filled the courtroom as the defendant was led in.","cn":"当被告被带进来的时候，整个法庭的人都激动起来，一片嘈杂。"}},{"pos":"N-SING 单数名词","cn":"（短暂的）快乐，兴奋","en":"If something gives you a buzz, it makes you feel very happy or excited for a short time.","ex":{"en":"Performing still gives him a buzz","cn":"表演仍然能让他兴奋不已。"}},{"pos":"N-SING 单数名词","cn":"热闹有趣的气氛；时尚氛围","en":"If a place or event has a buzz, it has a lively, interesting and modern atmosphere.","ex":{"en":"The girls fell in love with Dublin on previous visits. They said that what they liked was the buzz about the place.","cn":"姑娘们在前几次的游览中就爱上了都柏林，她们说她们喜欢这个城市的时尚氛围。"}},{"pos":"ADJ 形容词","cn":"（词语、想法或活动）时髦的","en":"You can use buzz to refer to a word, idea, or activity which has recently become extremely popular.","ex":{"en":"...the latest buzz phrase in garden design circles","cn":"园艺设计圈里的最新流行词语"}},{"pos":"VERB 动词","cn":"（用内线）给…打电话；（用蜂鸣器）呼叫","en":"If you buzz someone, you call them, usually using an internal telephone line or a buzzer.","ex":{"en":"Later that morning Julie buzzed me.","cn":"那天上午晚些时候朱丽给我打来了电话。"}},{"pos":"VERB 动词","cn":"（飞机）低飞掠过，逼近","en":"If an aircraft buzzes a place, it flies low over it, usually in a threatening way.","ex":{"en":"American fighter planes buzzed the city.","cn":"美国战斗机低飞掠过城市。"}},{"pos":"","cn":"","en":"相关词组：buzz off"}]},"examples":[{"en":"I've been buzzing around town all day sorting out my trip.","cn":"我一整天都在城里转来转去，安排旅行的事情。"},{"en":"My head was still buzzing after the day's events.","cn":"一天的活动结束后，我头脑中还是闹哄哄的。"}]},"burden":{"media":{"uk":"media/uk/burden__gb_1.mp3","us":"media/us/burden__us_1.mp3"},"oxford":{"phon":"ˈbɜːdn","pos":"noun","senses":[{"en":"a duty, responsibility, etc. that causes worry, difficulty or hard work","cn":"（义务、责任等的）重担，负担","ex":{"en":"to bear/carry/ease/reduce/share the burden","cn":"承受／担负／减轻／减少／分担重担"}},{"en":"a heavy load that is difficult to carry","cn":"重担；重负","lab":"formal"},{"en":"to give somebody a duty, responsibility, etc. that causes worry, difficulty or hard work","cn":"（使）担负（沉重或艰难的任务、职责等）","ex":{"en":"They have burdened themselves with a high mortgage.","cn":"他们负担了一笔很高的按揭借款。"},"pos":"verb"},{"en":"to be carrying something heavy","cn":"负重","ex":{"en":"She got off the bus, burdened with two heavy suitcases.","cn":"她提着两只沉重的手提箱下了公共汽车。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"负担；重负","en":"If you describe a problem or a responsibility as a burden, you mean that it causes someone a lot of difficulty, worry, or hard work.","ex":{"en":"The developing countries bear the burden of an enormous external debt","cn":"发展中国家背负着巨额外债。"}},{"pos":"N-COUNT 可数名词","cn":"重担；负荷","en":"A burden is a heavy load that is difficult to carry."},{"pos":"VERB 动词","cn":"使烦恼；烦扰","en":"If someone burdens you with something that is likely to worry you, for example a problem or a difficult decision, they tell you about it.","ex":{"en":"We decided not to burden him with the news.","cn":"我们决定不拿这个消息去烦他。"}},{"pos":"PHRASE 短语","cn":"举证责任","en":"The burden of proof is the task of proving that you are correct, for example when you have accused someone of a crime.","ex":{"en":"The burden of proof is on the prosecution.","cn":"起诉方有举证的责任。"}}]},"examples":[{"en":"I don't want to become a burden to my children when I'm old.","cn":"我不想在年老的时候成为孩子们的累赘。"},{"en":"She got off the bus, burdened with two heavy suitcases.","cn":"她提着两个沉重的手提箱下了公共汽车。"}]},"bubble":{"oxford":{"phon":"ˈbʌbl","pos":"noun","senses":[{"en":"a ball of air or gas in a liquid, or a ball of air inside a solid substance such as glass","cn":"泡；气泡","ex":{"en":"champagne bubbles","cn":"香槟酒的泡沫"}},{"en":"a round ball of liquid, containing air, produced by soap and water","cn":"肥皂泡","ex":{"en":"The children like to have bubbles in their bath.","cn":"孩子们喜欢浴盆里有肥皂泡。"}},{"en":"a small amount of a feeling that somebody wants to express","cn":"（欲表达的）一点感情","ex":{"en":"a bubble of laughter/hope/enthusiasm","cn":"一点笑声／希望／热心"}},{"en":"a good or lucky situation that is unlikely to last long","cn":"（很可能持续不长的）好景，好运；泡沫","ex":{"en":"Economists warned of a stock-market bubble.","cn":"经济学家警告说股市有泡沫。"}},{"en":"a small group of people with whom you are allowed to have physical contact during a period when social distancing is otherwise required","cn":"社交气泡（在实施社交距离的情况下允许一小群人在某段时间内相聚）","ex":{"en":"He's been staying with his sister and her husband at weekends since he chose to form a bubble with them.","cn":"自从他决定与姐姐、姐夫组成社交气泡后，就一直和他们一起度周末。"}},{"en":"to form bubbles","cn":"起泡；冒泡","g":"[intransitive]","ex":{"en":"The water in the pan was beginning to bubble.","cn":"锅里的水开始冒泡。"},"pos":"verb"},{"en":"to make a bubbling sound","cn":"发出冒气泡的声音","g":"[intransitive]","ex":{"en":"I could hear the soup bubbling away.","cn":"我能听到汤在咕嘟咕嘟地响。"},"pos":"verb"},{"en":"to be full of a particular feeling","cn":"洋溢着（某种感情）","g":"[intransitive]","ex":{"en":"She was bubbling over with excitement.","cn":"她兴奋不已。"},"pos":"verb"},{"en":"to be felt strongly by a person; to be present in a situation","cn":"被强烈感受；充溢；存在","g":"[intransitive]","ex":{"en":"Laughter bubbled up inside him.","cn":"他忍不住心中窃笑。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"泡；气泡","en":"Bubbles are small balls of air or gas in a liquid.","ex":{"en":"Ink particles attach themselves to air bubbles and rise to the surface.","cn":"墨汁颗粒附着在气泡上，浮到表面上。"}},{"pos":"N-COUNT 可数名词","cn":"肥皂泡","en":"A bubble is a hollow ball of soapy liquid that is floating in the air or standing on a surface.","ex":{"en":"With soap and water, bubbles and boats, children love bathtime.","cn":"有了肥皂、水、泡泡和小船，孩子们都喜欢洗澡。"}},{"pos":"N-COUNT 可数名词","cn":"（股票价值的）泡沫","en":"A bubble is a situation in which large numbers of people want to buy shares in a company that is new or not yet financially successful, and pay more than the shares are worth. When it becomes clear that the shares are worth less than people paid for them, you can say that the bubble has burst.","ex":{"en":"Everyone is hoping that these hi-tech companies will turn out to be the Microsofts of the future. At the moment they look more like the focus of a speculative bubble","cn":"每个人都希望这些高科技公司能成为未来的微软。目前它们看上去更像是投机泡沫的中心。"}},{"pos":"N-COUNT 可数名词","cn":"（漫画中显示人物对白的）气泡框，圆框","en":"In a cartoon, a speech bubble is the shape which surrounds the words which a character is thinking or saying."},{"pos":"VERB 动词","cn":"冒泡；沸腾","en":"When a liquid bubbles, bubbles move in it, for example because it is boiling or moving quickly.","ex":{"en":"Heat the seasoned stock until it is bubbling","cn":"将调好味的肉汤加热至沸腾。"}},{"pos":"VERB 动词","cn":"忙碌；活跃","en":"If something bubbles, it is very busy or lively.","ex":{"en":"At the same time, the press bubbles with stories of the sale of Russian arms to Serbia","cn":"与此同时，报纸上登满了俄罗斯向塞尔维亚出售武器的报道。"}},{"pos":"VERB 动词","cn":"不断出现；滔滔不绝","en":"A feeling, influence, or activity that is bubbling away continues to occur.","ex":{"en":"... political tensions that have been bubbling away for years","cn":"…持续多年的政治紧张局势"}},{"pos":"VERB 动词","cn":"滔滔不绝地说；洋溢着（某种感情）","en":"Someone who is bubbling with a good feeling is so full of it that they keep expressing the way they feel to everyone around them.","ex":{"en":"She came to the phone bubbling with excitement","cn":"她走到电话旁，兴奋地说个不停。"}},{"pos":"","cn":"","en":"相关词组：bubble over bubble up"}]},"media":{"img":["media/ldoce/img/bubble.jpg","media/pic/froth_comp.jpg"],"uk":"media/uk/bubble__gb_1.mp3","us":"media/us/bubble__us_1.mp3"},"examples":[{"en":"At the time the telecoms bubble was at its height.","cn":"当时电信业的泡沫正处于极度膨胀时期。"},{"en":"When the bubble finally burst, hundreds of people lost their jobs.","cn":"当泡沫最终破灭时，有几百人丢了饭碗。"}]},"bulletins":{"lemma":"bulletin"},"busy":{"media":{"uk":"media/uk/busy__gb_1.mp3","us":"media/us/busy__us_1.mp3"},"oxford":{"phon":"ˈbɪzi","pos":"adjective","senses":[{"en":"having a lot to do; perhaps not free to do something else because you are working on something","cn":"忙碌的；无暇的","sc":"doing something","ex":{"en":"Are you busy tonight?","cn":"你今晚忙吗？"}},{"en":"giving all your attention and effort to a particular activity","cn":"全身心忙于某事","sc":"doing something","ex":{"en":"James is busy practising for the school concert.","cn":"詹姆斯正忙着为学校音乐会排练。"}},{"en":"full of work and activity","cn":"工作忙的；充满活动的","sc":"period of time","ex":{"en":"Have you had a busy day?","cn":"你今天忙了一天吗？"}},{"en":"full of people, activity, vehicles, etc.","cn":"人来车往的；熙熙攘攘的","sc":"place","ex":{"en":"a busy road/street","cn":"繁忙的公路／街道"}},{"en":"being used","cn":"正被占用的；占线的","lab":"especially North American English","sc":"phone line","ex":{"en":"The line is busy—I'll try again later.","cn":"电话占线，我过会儿再打。"}},{"en":"too full of small details","cn":"杂乱的；纷繁的；令人眼花缭乱的","sc":"pattern/design","ex":{"en":"This wallpaper is too busy for the bedroom.","cn":"这壁纸的图案太乱，不适合用于卧室。"}},{"en":"to fill your time doing an activity or a task","cn":"忙着做某事","ex":{"en":"She busied herself with the preparations for the party.","cn":"她忙于准备晚会。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忙的；忙碌的","en":"When you are busy, you are working hard or concentrating on a task, so that you are not free to do anything else.","ex":{"en":"What is it? I'm busy","cn":"什么事？我忙着呢。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"繁忙的；忙碌的","en":"A busy time is a period of time during which you have a lot of things to do.","ex":{"en":"It'll have to wait. This is our busiest time ","cn":"这事得往后放。这是我们最忙碌的时候。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"全神贯注的；心无旁骛的；埋头于…的","en":"If you say that someone is busy thinking or worrying about something, you mean that it is taking all their attention, often to such an extent that they are unable to think about anything else.","ex":{"en":"Companies are so busy analysing the financial implications that they overlook the effect on workers ","cn":"公司忙于分析此事对财务可能产生的影响，而忽视了其对工人的影响。"}},{"pos":"VERB 动词","cn":"使（自己）忙于","en":"If you busy yourself with something, you occupy yourself by dealing with it.","ex":{"en":"He busied himself with the camera","cn":"他忙着摆弄那个相机。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"热闹的；忙碌的；熙熙攘攘的","en":"A busy place is full of people who are doing things or moving about.","ex":{"en":"The Strand is one of London's busiest and most affluent streets","cn":"斯特兰德街是伦敦最繁华、最富足的街道之一。"}},{"pos":"ADJ 形容词","cn":"占线的","en":"When a telephone line is busy, you cannot make your call because the line is already being used by someone else.","ex":{"en":"I tried to reach him, but the line was busy.","cn":"我试图和他联系，但他的电话占线。"}}]},"examples":[{"en":"I'm afraid the doctor is busy at the moment. Can he call you back?","cn":"恐怕医生现在没空。让他给你回话行吗？"},{"en":"Victoria is one of London's busiest stations.","cn":"维多利亚站是伦敦最繁忙的车站之一。"}]},"buckled":{"lemma":"buckle"},"buses":{"lemma":"bus","media":{"img":["media/pic/buses_comp.jpg","media/thumb/doubledecker.jpg"],"uk":"media/uk/bus__gb_1.mp3","us":"media/us/bus__us_1.mp3"}},"buttonholes":{"lemma":"buttonhole"},"buffet":{"media":{"uk":"media/uk/buffet__gb_1.mp3","us":"media/us/buffet__us_1.mp3"},"oxford":{"phon":"ˈbʌfeɪ","pos":"noun","senses":[{"en":"a meal at which people serve themselves from a table and then stand or sit somewhere else to eat","cn":"自助餐","ex":{"en":"a buffet lunch/supper","cn":"自助午餐／晚餐"}},{"en":"a place, for example in a train or bus station, where you can buy food and drinks to eat or drink there, or to take away","cn":"（火车）饮食柜台；（车站）快餐部"},{"en":"the part of a train where you can buy something to eat and drink","cn":"（火车）餐车","lab":"British English"},{"en":"a piece of furniture in a dining room for putting food on before it is served, with drawers in it for storing knives, forks, etc.","cn":"餐具柜","lab":"especially North American English"},{"en":"to knock or push somebody/something roughly from side to side","cn":"打来打去；推来搡去","lab":"figurative, formal，，","ex":{"en":"to be buffeted by the wind","cn":"被风吹得左右摇摆"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"自助餐","en":"A buffet is a meal of cold food that is displayed on a long table at a party or public occasion. Guests usually serve themselves from the table.","ex":{"en":"...a buffet lunch","cn":"自助午餐"}},{"pos":"N-COUNT 可数名词","cn":"（通常指旅馆或车站的）餐饮部，小餐馆","en":"A buffet is a café, usually in a hotel or station.","ex":{"en":"We sat in the station buffet sipping tea.","cn":"我们坐在车站的自助餐厅里喝茶。"}},{"pos":"N-COUNT 可数名词","cn":"（火车上的）餐车","en":"On a train, the buffet or the buffet car is the carriage or car where meals and snacks are sold."},{"pos":"VERB 动词","cn":"（大风或海浪）反复拍打，猛击","en":"If something is buffeted by strong winds or by stormy seas, it is repeatedly struck or blown around by them.","ex":{"en":"Their plane had been severely buffeted by storms","cn":"他们的飞机遭受到风暴的重创。"}},{"pos":"VERB 动词","cn":"（严峻局势）冲击，打击","en":"If an economy or government is buffeted by difficult or unpleasant situations, it experiences many of them.","ex":{"en":"The whole of Africa had been buffeted by social and political upheavals.","cn":"整个非洲都经受了社会和政治动荡之苦。"}}]},"examples":[{"en":"Dinner will be a cold buffet, not a sit-down meal.","cn":"主餐是自助冷食，不是坐着等服务员送来的那种。"},{"en":"( figurative, formal ) The nation had been buffeted by a wave of strikes.","cn":"罢工浪潮使这个国家受到了重创。"}]},"burning":{"media":{"uk":"media/uk/burning__gb_1.mp3","us":"media/us/burning__us_1.mp3"},"oxford":{"phon":"ˈbɜːnɪŋ","pos":"adjective","senses":[{"en":"very strong; extreme","cn":"强烈的；极度的","ex":{"en":"a burning desire to win","cn":"取胜的迫切愿望"}},{"en":"a very important problem that requires immediate attention","cn":"重大急迫的问题；当务之急","ex":{"en":"one of the burning issues of the day","cn":"当今最紧迫的问题之一"}},{"en":"very strong and giving a feeling of burning","cn":"强烈的；火辣辣的","ex":{"en":"She felt a burning sensation in her throat.","cn":"她感到咽喉火辣辣的疼。"}},{"en":"very hot; looking and feeling very hot","cn":"炽热的；（看似或感觉）热辣辣的","ex":{"en":"the burning sun","cn":"灼热的太阳"}},{"en":"eyes that seem to be staring at you very hard","cn":"（目光）紧盯着的，灼热的","lab":"literary"},{"en":"very hot","cn":"（形容热）火烧一样","pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"灼热的；炙热的","en":"You use burning to describe something that is extremely hot.","ex":{"en":"...the burning desert of Central Asia.","cn":"炙热的中亚沙漠"}},{"pos":"ADJ 形容词","cn":"热烈的；热切的；强烈的","en":"If you say that someone has burning eyes, you mean they look at you in an intense way or have bright eyes because of a strong feeling.","ex":{"en":"She glared at both of them with burning, reproachful eyes.","cn":"她瞪着他们俩，目光中充满怒火和责备。"}},{"pos":"ADJ 形容词","cn":"（兴趣）浓厚的；（欲望）强烈的","en":"If you have a burning interest in something or a burning desire to do something, you are extremely interested in it or want to do it very much.","ex":{"en":"I had a burning ambition to become a journalist.","cn":"我热切期盼成为一名记者。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"急迫的；重要的","en":"A burning issue or question is a very important or urgent one that people feel very strongly about.","ex":{"en":"The burning question in this year's debate over the federal budget is: whose taxes should be raised?","cn":"今年联邦财政预算辩论中的一个重要问题就是：哪些人的纳税额应该提高？"}}]},"examples":[{"en":"He's always had a burning ambition to start his own business.","cn":"他总是雄心勃勃地想自己创业。"},{"en":"a burning desire to win","cn":"取胜的迫切愿望"}],"base":"burn"},"buckle":{"oxford":{"phon":"ˈbʌkl","pos":"verb","senses":[{"en":"to fasten something or be fastened with a buckle","cn":"（使）搭扣扣住","g":"[transitive, intransitive]","ex":{"en":"She buckled her belt.","cn":"她扣上了腰带。"}},{"en":"to become bent, damaged or broken under a weight or force; to bend, damage or break something in this way","cn":"（被）压垮，压弯","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"The steel frames began to buckle under the strain.","cn":"钢架在重压下开始变形。"}},{"en":"when your knees or legs buckle or when you buckle at the knees, your knees become weak and you start to fall","cn":"双腿发软","g":"[intransitive]"},{"en":"a piece of metal or plastic used for joining the ends of a belt or for fastening a part of a bag, shoe, etc.","cn":"（皮带等的）搭扣，锁扣","ex":{"en":"shoes with silver buckles","cn":"带银扣的鞋子"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（皮带等的）搭扣，搭钩","en":"A buckle is a piece of metal or plastic attached to one end of a belt or strap, which is used to fasten it.","ex":{"en":"He wore a belt with a large brass buckle.","cn":"他系了条带有一个大的铜搭扣的皮带。"}},{"pos":"VERB 动词","cn":"扣住；扣紧","en":"When you buckle a belt or strap, you fasten it.","ex":{"en":"A door slammed in the house and a man came out buckling his belt.","cn":"房子里的一扇门砰地关上，一个男子边扣腰带边走了出来。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（因受热或受力）（使）弯曲，（使）变形","en":"If an object buckles or if something buckles it, it becomes bent as a result of very great heat or force.","ex":{"en":"The door was beginning to buckle from the intense heat","cn":"门在高温高热下开始变形。"}},{"pos":"VERB 动词","cn":"（双腿或膝盖因虚弱、劳累）发软","en":"If your legs or knees buckle, they bend because they have become very weak or tired.","ex":{"en":"Mcanally's knees buckled and he crumpled down onto the floor","cn":"麦卡纳利双膝发软，瘫倒在地板上。"}},{"pos":"","cn":"","en":"相关词组：buckle down buckle under buckle up"}]},"media":{"img":["media/pic/fasteners_clothes_comp.jpg","media/thumb/buckle.jpg"],"uk":"media/uk/buckle__gb_1.mp3","us":"media/us/buckle__us_1.mp3"},"examples":[{"en":"( figurative ) A weaker man would have buckled under the pressure.","cn":"意志薄弱的人在这种压力下可能就垮了。"},{"en":"I'd better buckle down to those reports.","cn":"我最好认真静下来努力完成那些报告。"}]},"burnout":{"media":{"uk":"media/uk/burnout__gb_1.mp3","us":"media/us/burnout__us_1.mp3"},"oxford":{"phon":"ˈbɜːnaʊt","pos":"noun","senses":[{"en":"the state of being extremely tired or ill, either physically or mentally, because you have worked too hard","cn":"精疲力竭；过度劳累"},{"en":"the point at which a rocket has used all of its fuel and has no more power","cn":"（火箭）熄火点，燃烧终止"}]},"examples":[{"en":"Many of the teachers are suffering from burnout.","cn":"许多老师产生了倦怠。"}]},"buttonhole":{"oxford":{"phon":"ˈbʌtnhəʊl","pos":"noun","senses":[{"en":"a hole on a piece of clothing for a button to be put through","cn":"纽扣孔；扣眼"},{"en":"a flower that is worn in the buttonhole of a coat or jacket","cn":"佩戴在扣眼上的花","lab":"British English"},{"en":"to make somebody stop and listen to you, especially when they do not want to","cn":"勉强（某人）停下来听","ex":{"en":"He buttonholed me just as I was going home.","cn":"当我正要回家时，他扣住了我的扣子。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纽孔；扣眼","en":"A buttonhole is a hole that you push a button through in order to fasten a shirt, coat, or other piece of clothing."},{"pos":"N-COUNT 可数名词","cn":"别在衣服上的花；胸花","en":"A buttonhole is a flower that you wear on your coat or dress."},{"pos":"VERB 动词","cn":"强留（某人）停下来听","en":"If you buttonhole someone, you stop them and make them listen to you.","ex":{"en":"Several people buttonholed television reporters to explain to them their reasons for not voting.","cn":"几个人拉住电视台记者非要向他们解释自己不投票的理由。"}}]},"media":{"uk":"media/uk/buttonhole__gb_1.mp3","us":"media/us/buttonhole__us_1.mp3"}},"bustling":{"media":{"uk":"media/uk/bustling__gb_1.mp3","us":"media/us/bustling__us_1.mp3"},"oxford":{"phon":"ˈbʌslɪŋ","pos":"adjective","senses":[{"en":"full of people moving about in a busy way","cn":"繁忙的；熙熙攘攘的","ex":{"en":"a bustling city","cn":"熙熙攘攘的城市"}}]},"examples":[{"en":"The market was bustling with life.","cn":"市场一片蓬勃。"},{"en":"a bustling city","cn":"熙熙攘攘的城市"}],"base":"bustle"},"building":{"media":{"img":["media/pic/buildings_comp.jpg","media/thumb/statelyhome.jpg"],"uk":"media/uk/building__gb_1.mp3","us":"media/us/building__us_1.mp3"},"oxford":{"phon":"ˈbɪldɪŋ","pos":"noun","senses":[{"en":"a structure such as a house or school that has a roof and walls","cn":"建筑物；房子；楼房","g":"[countable]","lab":"British English","ex":{"en":"a tall/high-rise/ten-storey building","cn":"高大／高层／十层建筑"}},{"en":"the process and work of making a structure","cn":"建筑；建筑业","g":"[uncountable]","ex":{"en":"the building of the school","cn":"学校的修建"}},{"en":"the creation or development of something","cn":"某物的创造或发展","g":"[uncountable]","ex":{"en":"The building of a consensus is not going to be an easy process.","cn":"建立共识并不是一个容易的过程。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"建筑物；房屋","en":"A building is a structure that has a roof and walls, for example a house or a factory.","ex":{"en":"They were on the upper floor of the building","cn":"他们在这座建筑物的楼上。"}}]},"examples":[{"en":"The company is looking for larger premises.","cn":"这家公司正在寻找更大的营业场所。"},{"en":"We have a buyer who would like to view the property.","cn":"我们有一买主想看看这房产。"}],"base":"build"},"bullet":{"oxford":{"phon":"ˈbʊlɪt","pos":"noun","senses":[{"en":"a small metal object that is fired from a gun","cn":"子弹；弹丸","ex":{"en":"He was found to have a single bullet wound in his chest.","cn":"发现他的胸部仅有一处枪伤。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"子弹","en":"A bullet is a small piece of metal with a pointed or rounded end, which is fired out of a gun."},{"pos":"PHRASE 短语","cn":"硬着头皮做；咬紧牙关应付","en":"If someone bites the bullet, they accept that they have to do something unpleasant but necessary.","ex":{"en":"Tour operators may be forced to bite the bullet and cut prices.","cn":"旅行社的经营者们可能不得不忍痛降价。"}}]},"media":{"uk":"media/uk/bullet__gb_1.mp3","us":"media/us/bullet__us_1.mp3"},"examples":[{"en":"He was killed by a bullet in the head.","cn":"他头部中弹死亡。"},{"en":"There were bullet holes in the door.","cn":"门上有弹孔。"}]},"bunches":{"lemma":"bunch","media":{"img":["media/pic/fruit_comp.jpg","media/thumb/grape.jpg"],"uk":"media/uk/bunch__gb_1.mp3","us":"media/us/bunch__us_1.mp3"}},"bunch":{"media":{"img":["media/ldoce/img/bunch.jpg","media/pic/fruit_comp.jpg"],"uk":"media/uk/bunch__gb_1.mp3","us":"media/us/bunch__us_1.mp3"},"oxford":{"phon":"bʌntʃ","pos":"noun","senses":[{"en":"a number of things of the same type which are growing or fastened together","cn":"串；束；扎","g":"[countable]","ex":{"en":"a bunch of bananas, grapes, etc.","cn":"一把香蕉、一串葡萄等"}},{"en":"a large amount of something; a large number of things or people","cn":"大量；大批","g":"[singular]","lab":"informal, especially North American English，，","ex":{"en":"I have a whole bunch of stuff to do this morning.","cn":"我今天上午有一大堆活儿要做。"}},{"en":"a group of people","cn":"群体","g":"[singular]","lab":"informal","ex":{"en":"The people that I work with are a great bunch.","cn":"和我一起工作的那些人很不错。"}},{"en":"long hair that is divided in two and tied at each side of the head","cn":"（扎在头两侧的）发辫","g":"[plural]","lab":"British English","ex":{"en":"She wore her hair in bunches.","cn":"她梳着两条辫子。"}},{"en":"to become tight or to form tight folds; to make something do this","cn":"（使）变紧，成皱褶","ex":{"en":"His muscles bunched under his shirt.","cn":"他衬衫下面的肌肉紧绷绷的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一伙，一群（人）","en":"A bunch of people is a group of people who share one or more characteristics or who are doing something together.","ex":{"en":"My neighbours are a bunch of busybodies","cn":"我的邻居们是一群爱管闲事的人。"}},{"pos":"N-COUNT 可数名词","cn":"一束（花）","en":"A bunch of flowers is a number of flowers with their stalks held or tied together.","ex":{"en":"He had left a huge bunch of flowers in her hotel room.","cn":"他在她宾馆房间里留下了一大束花。"}},{"pos":"N-COUNT 可数名词","cn":"一串（香蕉或葡萄）","en":"A bunch of bananas or grapes is a group of them growing on the same stem.","ex":{"en":"Lili had fallen asleep clutching a fat bunch of grapes.","cn":"莉莉手里抓着一大串葡萄睡着了。"}},{"pos":"N-COUNT 可数名词","cn":"一串（钥匙）","en":"A bunch of keys is a set of keys kept together on a metal ring.","ex":{"en":"George took out a bunch of keys and went to work on the complicated lock.","cn":"乔治掏出一串钥匙，上前去鼓捣那把结构复杂的锁。"}},{"pos":"QUANT 数量词","cn":"大量；大批","en":"A bunch of things is a number of things, especially a large number.","ex":{"en":"We did a bunch of songs together.","cn":"我们一起唱了很多首歌。"}},{"pos":"N-PLURAL 复数名词","cn":"（扎在女子脑后两侧的）发辫","en":"If a girl has her hair in bunches, it is parted down the middle and tied on each side of her head."},{"pos":"VERB 动词","cn":"(衣服）打褶","en":"If clothing bunches around a part of your body, it forms a set of creases around it.","ex":{"en":"She clutches the sides of her skirt until it bunches around her waist.","cn":"她捏着裙子的两侧，直到裙子在她腰部打起了褶。"}},{"pos":"PHRASE 短语","cn":"同类中最好的；出类拔萃者；精华","en":"If you say someone or something is the best of the bunch or the pick of the bunch, you mean they are the best of a group of people or things.","ex":{"en":"I watched every game of the World Cup and Craig was the pick of the bunch.","cn":"我观看了世界杯的每场比赛，克雷格是表现最出色的。"}},{"pos":"","cn":"","en":"相关词组：bunch up"}]},"examples":[{"en":"The people that I work with are a great bunch.","cn":"和我一起工作的那些人很不错。"},{"en":"The sheep bunched together as soon as they saw the dog.","cn":"那些绵羊一见到狗就挤作一团。"}]},"butterfly":{"oxford":{"phon":"ˈbʌtəflaɪ","pos":"noun","senses":[{"en":"a flying insect with a long thin body and four large, usually brightly coloured, wings","cn":"蝴蝶","g":"[countable]","ex":{"en":"butterflies and moths","cn":"蝴蝶和蛾"}},{"en":"a swimming stroke in which you swim on your front and lift both arms forward at the same time while your legs move up and down together","cn":"蝶泳","g":"[uncountable]","ex":{"en":"She was third in the 200m butterfly (= a swimming race).","cn":"她得了 200 米蝶泳比赛的第三名。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蝴蝶","en":"A butterfly is an insect with large colourful wings and a thin body."},{"pos":"N-UNCOUNT 不可数名词","cn":"蝶泳","en":"Butterfly is a swimming stroke which you do lying on your front, kicking your legs and bringing your arms over your head together."},{"pos":"PHRASE 短语","cn":"情绪紧张；心慌意乱；忐忑不安","en":"If you have butterflies in your stomach or have butterflies, you are very nervous or excited about something.","ex":{"en":"An exam, or even an exciting social event may produce butterflies in the stomach.","cn":"一场考试，甚至是一次令人兴奋的社会活动，都有可能让人心里发慌。"}}]},"media":{"img":["media/ldoce/img/butterfly.jpg","media/pic/insects_comp.jpg"],"uk":"media/uk/butterfly__gb_1.mp3","us":"media/us/butterfly__us_1.mp3"},"examples":[{"en":"She's like a butterfly. She flits in and out of people's lives.","cn":"她像一只蝴蝶，每天在人前人后飞来飞去。"},{"en":"She was third in the 200m butterfly (= a swimming race).","cn":"她得了 200 米蝶泳比赛的第三名。"}]},"budget":{"media":{"uk":"media/uk/budget__gb_1.mp3","us":"media/us/budget__us_1.mp3"},"oxford":{"phon":"ˈbʌdʒɪt","pos":"noun","senses":[{"en":"the money that is available to a person or an organization and a plan of how it will be spent over a period of time","cn":"预算","g":"[countable, uncountable]","lab":"North American English","ex":{"en":"an annual budget of £10 million","cn":"1 000 万英镑的年度预算"}},{"en":"an official statement by the government of a country’s income from taxes, etc. and how it will be spent","cn":"政府的年度预算","g":"[countable, usually singular]","lab":"British English also","ex":{"en":"Tax cuts are expected to be a major part of this year's Budget.","cn":"减税预计将成为今年预算的主要部分。"}},{"en":"to be careful about the amount of money you spend; to plan to spend an amount of money for a particular purpose","cn":"谨慎花钱；把…编入预算","ex":{"en":"If we budget carefully we'll be able to afford the trip.","cn":"我们精打细算一点，就能够负担这次旅行。"},"pos":"verb"},{"en":"low in price","cn":"价格低廉的；花钱少的","ex":{"en":"a budget flight/hotel","cn":"便宜的航班／旅馆"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"预算","en":"Your budget is the amount of money that you have available to spend. The budget for something is the amount of money that a person, organization, or country has available to spend on it.","ex":{"en":"She will design a fantastic new kitchen for you — and all within your budget","cn":"她将为你设计一个超级棒的新厨房，而且绝不会超出你的预算。"}},{"pos":"N-COUNT 可数名词","cn":"财政收支状况","en":"The budget of an organization or country is its financial situation, considered as the difference between the money it receives and the money it spends.","ex":{"en":"The hospital obviously needs to balance the budget each year.","cn":"很明显，医院每年都要平衡其收支预算。"}},{"pos":"N-PROPER 专有名词","cn":"（英国的）政府年度预算案，政府年度预算演讲","en":"In Britain, the Budget is the financial plan in which the government states how much money it intends to raise through taxes and how it intends to spend it. The Budget is also the speech in which this plan is announced.","ex":{"en":"The Chancellor could use the Budget to bring in taxation reforms.","cn":"财政大臣可以利用政府年度预算演讲的机会提出税收改革事宜。"}},{"pos":"VERB 动词","cn":"把…编入预算","en":"If you budget certain amounts of money for particular things, you decide that you can afford to spend those amounts on those things.","ex":{"en":"The company has budgeted $10 million for advertising","cn":"公司已经做了1,000万美元的广告预算。"}},{"pos":"ADJ 形容词","cn":"（用于广告语）低价的，低廉的","en":"Budget is used in advertising to suggest that something is being sold cheaply.","ex":{"en":"Cheap flights are available from budget travel agent from £240.","cn":"收费低廉的旅行社可以提供240英镑起的低价机票。"}},{"pos":"","cn":"","en":"相关词组：budget for"}]},"examples":[{"en":"If we budget carefully we'll be able to afford the trip.","cn":"我们精打细算一点，就能够负担这次旅行。"},{"en":"Ten million francs has been budgeted for the project.","cn":"为该工程已编制了一千万法郎的预算。"}]},"bundle":{"media":{"uk":"media/uk/bundle__gb_1.mp3","us":"media/us/bundle__us_1.mp3"},"oxford":{"phon":"ˈbʌndl","pos":"noun","senses":[{"en":"a number of things tied or wrapped together; something that is wrapped up","cn":"（一）捆，包，扎","g":"[countable]","ex":{"en":"a bundle of rags/papers/firewood","cn":"一捆碎布／报纸／木柴"}},{"en":"a number of things that belong, or are sold together","cn":"一批（同类事物或出售的货品）","g":"[countable]","ex":{"en":"a bundle of ideas","cn":"一套想法"}},{"en":"a person or thing that makes you laugh","cn":"风趣的人；笑料","g":"[singular]","lab":"informal","ex":{"en":"He wasn't exactly a bundle of laughs (= a happy person to be with) last night.","cn":"他昨晚有点让人扫兴。"}},{"en":"a large amount of money","cn":"一大笔钱","g":"[singular]","lab":"informal","ex":{"en":"That car must have cost a bundle.","cn":"那部车一定价格不菲。"}},{"en":"to push or send somebody somewhere quickly and not carefully","cn":"匆匆送走；推搡；赶","g":"[transitive]","ex":{"en":"They bundled her into the back of a car.","cn":"他们把她塞进了车后座。"},"pos":"verb"},{"en":"to move somewhere quickly in a group","cn":"（成群地）匆忙赶往","g":"[intransitive]","ex":{"en":"We bundled out onto the street.","cn":"我们大伙急忙跑到街上。"},"pos":"verb"},{"en":"to supply extra equipment, especially software when selling a new computer, at no extra cost","cn":"额外免费提供（设备等）；（尤指出售计算机时）赠送软件","g":"[transitive]","ex":{"en":"A further nine applications are bundled with the system.","cn":"该系统免费附送九套应用软件。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"捆；束；包","en":"A bundle of things is a number of them that are tied together or wrapped in a cloth or bag so that they can be carried or stored.","ex":{"en":"She produced a bundle of notes and proceeded to count out one hundred and ninety-five pounds","cn":"她拿出一捆钞票，接着数出了195英镑。"}},{"pos":"N-COUNT 可数名词","cn":"婴儿","en":"You can refer to a tiny baby as a bundle ."},{"pos":"N-SING 单数名词","cn":"极度，非常（用于强调某人具备的某种品质或特性）","en":"If you describe someone as, for example, a bundle of fun, you are emphasizing that they are full of fun. If you describe someone as a bundle of nerves, you are emphasizing that they are very nervous.","ex":{"en":"I remember Mickey as a bundle of fun, great to have around","cn":"我记得米基是个很有趣的人，和他在一起非常愉快。"}},{"pos":"N-COUNT 可数名词","cn":"大量；广泛","en":"If you refer to a bundle of things, you are emphasizing that there is a wide range of them.","ex":{"en":"The profession offers a bundle of benefits, not least of which is extensive training.","cn":"这份职业提供了大量福利，全面训练就是其中很重要的一项。"}},{"pos":"VERB 动词","cn":"匆忙打发；推搡","en":"If someone is bundled somewhere, someone pushes them there in a rough and hurried way.","ex":{"en":"He was bundled into a car and driven 50 miles to a police station","cn":"他被塞进一部车里，带到50英里外的警察局。"}},{"pos":"VERB 动词","cn":"捆绑销售（软件）","en":"To bundle software means to sell it together with a computer, or with other hardware or software, as part of a set.","ex":{"en":"It's cheaper to buy software bundled with a PC than separately.","cn":"购买和个人电脑一起捆绑销售的软件要比单买便宜。"}},{"pos":"PHRASE 短语","cn":"花费（某人）一大笔钱","en":"If you say that something costs a bundle, or costs someone a bundle, you are emphasizing that it is expensive.","ex":{"en":"You can have it, but it'll cost you a bundle.","cn":"你可以买下它，不过你要花一大笔钱。"}},{"pos":"","cn":"","en":"相关词组：bundle off bundle up"}]},"examples":[{"en":"I bundled her up in a blanket and gave her a hot drink.","cn":"我给她裹了条毯子，又给了她一杯热饮。"},{"en":"She held her little bundle (= her baby) tightly in her arms.","cn":"她怀中紧紧地抱着襁褓中的婴儿。"}]},"bursting":{"lemma":"burst"},"buy":{"media":{"uk":"media/uk/buy__gb_1.mp3","us":"media/us/buy__us_1.mp3"},"oxford":{"phon":"baɪ","pos":"verb","senses":[{"en":"to obtain something by paying money for it","cn":"买；购买","g":"[transitive, intransitive]","lab":"informal","sc":"with money","ex":{"en":"Where did you buy that dress?","cn":"那件连衣裙你是在哪里买的？"}},{"en":"to be enough to pay for something","cn":"够支付","g":"[transitive]","sc":"with money","ex":{"en":"He gave his children the best education that money can buy.","cn":"他让孩子们接受花钱能买到的最好的教育。"}},{"en":"to persuade somebody to do something dishonest in return for money","cn":"买通；收买；贿赂","g":"[transitive]","sc":"with money","ex":{"en":"He can't be bought (= he's too honest to accept money in this way).","cn":"他是收买不了的。"}},{"en":"to obtain something by losing something else of great value","cn":"付出极大的代价而获得","g":"[transitive, usually passive]","sc":"obtain","ex":{"en":"Her fame was bought at the expense of her marriage.","cn":"她出了名，却牺牲了她的婚姻。"}},{"en":"to believe that something is true, especially something that is not very likely","cn":"相信（尤指不大可能的事）","g":"[transitive]","lab":"informal","sc":"believe","ex":{"en":"You could say you were ill but I don't think they'd buy it (= accept the explanation).","cn":"你可以称病，但我想他们不会相信的。"}},{"en":"a thing that is worth the money that you pay for it","cn":"合算的商品","sc":"something bought","ex":{"en":"That jacket was a really good buy.","cn":"那件夹克确实买得很划算。"},"pos":"noun"},{"en":"something that is bought or that is for sale; the act of buying something","cn":"买进（或出售）的东西；购买","sc":"something bought","ex":{"en":"Computer games are a popular buy this Christmas.","cn":"这个圣诞节电脑游戏很畅销。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"买；购买","en":"If you buy something, you obtain it by paying money for it.","ex":{"en":"He could not afford to buy a house","cn":"他买不起房子。"}},{"pos":"VERB 动词","cn":"买到；能买；够买","en":"If you talk about the quantity or standard of goods an amount of money buys, you are referring to the price of the goods or the value of the money.","ex":{"en":"About £35,000 buys a habitable house","cn":"大约花3.5万英镑就能买到一所宜居的房子。"}},{"pos":"VERB 动词","cn":"（争取或付出一定代价以）获得，赢得","en":"If you buy something like time, freedom, or victory, you obtain it but only by offering or giving up something in return.","ex":{"en":"It was a risky operation, but might buy more time","cn":"这是一次冒险的行动，但也许能赢得更多的时间。"}},{"pos":"VERB 动词","cn":"收买；贿赂","en":"If you say that a person can be bought, you are criticizing the fact that they will give their help or loyalty to someone in return for money.","ex":{"en":"Once he shows he can be bought, they settle down to a regular payment.","cn":"一旦他表现出可以被收买，他们就会定期向他行贿。"}},{"pos":"VERB 动词","cn":"相信；接受","en":"If you buy an idea or a theory, you believe and accept it.","ex":{"en":"I'm not buying any of that nonsense.","cn":"我才不信那些废话呢。"}},{"pos":"N-COUNT 可数名词","cn":"划算的东西；性价比高的商品","en":"If something is a good buy, it is of good quality and not very expensive.","ex":{"en":"This was still a good buy even at the higher price","cn":"即使价格更高一些，这仍然很合算。"}},{"pos":"","cn":"","en":"相关词组：buy into buy off buy out buy up"}]},"examples":[{"en":"He gave his children the best education that money can buy.","cn":"他让孩子们接受花钱能买到的最好的教育。"},{"en":"She had never bought into the idea that to be attractive you have to be thin.","cn":"她从不随大溜认为要想有魅力，就得瘦身。"}]},"bush":{"media":{"uk":"media/uk/bush__gb_1.mp3","us":"media/us/bush__us_1.mp3"},"oxford":{"phon":"bʊʃ","pos":"noun","senses":[{"en":"a plant that grows thickly with several hard stems coming up from the root","cn":"灌木","g":"[countable]","ex":{"en":"a rose/holly bush","cn":"玫瑰丛；冬青树丛"}},{"en":"a thing that looks like a bush, especially an area of thick hair or fur","cn":"灌木状的东西（尤指浓密的毛发或皮毛）","g":"[countable]"},{"en":"an area of wild land that has not been cleared, especially in Africa and Australia; in New Zealand an area where the forest has not been cleared","cn":"（尤指非洲和澳大利亚的）荒野，丛林；（新西兰的）林区","g":"[uncountable]","ex":{"en":"Children are taught from an early age how to survive in the bush.","cn":"孩子们从小就学习在荒野中求生的方法。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"灌木；灌木丛","en":"A bush is a large plant which is smaller than a tree and has a lot of branches.","ex":{"en":"Trees and bushes grew down to the water's edge.","cn":"树和灌木丛一直长到了水边。"}},{"pos":"N-SING 单数名词","cn":"（热带国家未开发的）荒野地带，丛林地带","en":"The wild, uncultivated parts of some hot countries are referred to as the bush.","ex":{"en":"They walked through the dense Mozambican bush for thirty six hours","cn":"他们花了36个小时穿过茂密的莫桑比克丛林。"}},{"pos":"PHRASE 短语","cn":"拐弯抹角；旁敲侧击","en":"If you tell someone not to beat about the bush, you mean that you want them to tell you something immediately and quickly, rather than in a complicated, indirect way.","ex":{"en":"Stop beating about the bush. What's he done?","cn":"别再拐弯抹角了，他到底干了什么？"}}]},"examples":[{"en":"holly bushes","cn":"冬青树丛"},{"en":"a rose bush","cn":"玫瑰丛"}]},"buckets":{"lemma":"bucket"},"buys":{"lemma":"buy","media":{"uk":"media/uk/buy__gb_1.mp3","us":"media/us/buy__us_1.mp3"}},"bury":{"oxford":{"phon":"ˈberi","pos":"verb","senses":[{"en":"to place a dead body in the ground","cn":"埋葬；安葬","lab":"figurative","sc":"dead person","ex":{"en":"They killed her and buried her body.","cn":"他们杀了她并把尸体埋了。"}},{"en":"to lose somebody by death","cn":"丧失（某人）","lab":"old-fashioned","sc":"dead person","ex":{"en":"She's 85 and has buried three husbands.","cn":"她 85 岁了，三度丧夫。"}},{"en":"to hide something in the ground","cn":"把（某物）掩藏在地下；埋藏","sc":"hide in ground","ex":{"en":"We used to dig for hours, looking for buried treasure.","cn":"我们为了寻找埋在地下的财宝曾连续挖了几个小时。"}},{"en":"to cover somebody/something with soil, rocks, leaves, etc.","cn":"（以土、石、树叶等）覆盖","g":"[often passive]","sc":"cover","ex":{"en":"A landslide buried about 25 people yesterday.","cn":"昨天发生的山体滑坡导致约25人被埋。"}},{"en":"to cover something so that it cannot be seen","cn":"遮盖；掩盖","sc":"cover","ex":{"en":"Your letter got buried under a pile of papers.","cn":"你的信被压在一堆文件底下。"}},{"en":"to ignore or hide a feeling, a mistake, etc.","cn":"不顾，掩藏（感情、错误等）","sc":"hide feeling","ex":{"en":"She had learnt to bury her feelings.","cn":"她已经学会了感情不外露。"}},{"en":"to put something deeply into something else","cn":"使陷入，把…插入（某物）","sc":"put deeply into something","ex":{"en":"He walked slowly, his hands buried in his pockets.","cn":"他双手插在口袋里缓步而行。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"掩埋；埋藏","en":"To bury something means to put it into a hole in the ground and cover it up with earth.","ex":{"en":"They make the charcoal by burying wood in the ground and then slowly burning it.","cn":"他们通过把木材埋到地下缓慢燃烧来获取木炭。"}},{"pos":"VERB 动词","cn":"埋葬；安葬","en":"To bury a dead person means to put their body into a grave and cover it with earth.","ex":{"en":"...soldiers who helped to bury the dead in large communal graves","cn":"帮忙把死者安葬在大型公共墓地的士兵们"}},{"pos":"VERB 动词","cn":"失去（亲人）","en":"If someone says they have buried one of their relatives, they mean that one of their relatives has died.","ex":{"en":"He had buried his wife some two years before he retired.","cn":"大概在他退休前两年，他妻子去世了。"}},{"pos":"VERB 动词","cn":"掩藏；埋藏","en":"If you bury something under a large quantity of things, you put it there, often in order to hide it.","ex":{"en":"She buried it under some leaves","cn":"她把它藏在一堆树叶下面。"}},{"pos":"VERB 动词","cn":"覆盖；掩埋；把…埋在下面","en":"If something buries a place or person, it falls on top of them so that it completely covers them and often harms them in some way.","ex":{"en":"Latest reports say that mud slides buried entire villages","cn":"最新报道说泥石流掩埋了整个整个的村庄。"}},{"pos":"VERB 动词","cn":"（因不高兴而）把（头或脸）贴（或靠）在…","en":"If you bury your head or face in something, you press your head or face against it, often because you are unhappy.","ex":{"en":"She buried her face in the pillows ","cn":"她把脸埋进枕头里。"}},{"pos":"VERB 动词","cn":"深藏；深埋","en":"If something buries itself somewhere, or if you bury it there, it is pushed very deeply in there.","ex":{"en":"The missile buried itself deep in the grassy hillside","cn":"导弹深深地埋在杂草丛生的山坡上。"}},{"pos":"VERB 动词","cn":"掩藏（感情）；抛开（记忆）","en":"If you bury a feeling, you try not to show it. If you bury a memory, you try to forget it.","ex":{"en":"When we feel anger, we bury the emotion and feel guilty instead","cn":"当我们感到愤怒时，压抑这种情绪反而会觉得内疚。"}},{"pos":"VERB 动词","cn":"藏身于；埋头于；专心于","en":"If you bury yourself in a place or in an activity such as your work, you spend all your time in that place or doing that activity, usually because you want to forget about things.","ex":{"en":"His reaction was to withdraw, to bury himself in work.","cn":"他的反应是抽身而退，埋头于工作。"}},{"pos":"VERB 动词","cn":"沉浸于；专心致志于","en":"If you bury your head in something such as a book or newspaper, or bury yourself in it, you look at it closely and concentrate very hard on it.","ex":{"en":"My father buried his head in his newspaper","cn":"我父亲专心致志地看他的报纸。"}},{"pos":"","cn":"","en":"to bury the hatchet→see: ;"}]},"media":{"uk":"media/uk/bury__gb_1.mp3","us":"media/us/bury__us_1.mp3"},"examples":[{"en":"Since she left, he's buried himself in his work.","cn":"自从她走后，他全心扑在工作上。"},{"en":"( figurative ) Their ambitions were finally dead and buried.","cn":"他们的雄心壮志最终给埋葬了。"}]},"buzzword":{"media":{"uk":"media/uk/buzzword__gb_1.mp3","us":"media/us/buzzword__us_1.mp3"},"oxford":{"phon":"ˈbʌzwɜːd","pos":"noun","senses":[{"en":"a word or phrase, especially one connected with a particular subject, that has become fashionable and popular and is used a lot in newspapers, etc.","cn":"（报刊等的）时髦术语，流行行话","ex":{"en":"Globalization is an international buzzword.","cn":"全球化是个国际流行语。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（媒体上的）时髦术语，流行行话","en":"A buzzword is a word or expression that has become fashionable in a particular field and is being used a lot by the media.","ex":{"en":"Biodiversity was the buzzword of the Rio Earth Summit.","cn":"生物多样性是里约热内卢地球峰会上的时髦词儿。"}}]},"examples":[{"en":"‘Multimedia’ has been a buzzword in the computer industry for years. “","cn":"多媒体”这个词语在计算机行业里已经流行多年了。"}]},"built":{"media":{"uk":"media/uk/built__gb_2.mp3","us":"media/us/built__us_2.mp3"},"oxford":{"phon":"bɪlt","pos":"combining form","senses":[{"en":"made in the particular way that is mentioned","cn":"…建成的；…造的","ex":{"en":"a newly built station","cn":"新建的车站"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Built is the past tense and past participle of build ."},{"pos":"ADJ 形容词","cn":"体形…的","en":"If you say that someone is built in a particular way, you are describing the kind of body they have.","ex":{"en":"All the Trollope boys were heavily built and quite tall.","cn":"特罗洛普家的所有男孩都是体格强壮、身材高大。"}}]},"examples":[{"en":"American-built cars","cn":"美国制造的汽车"},{"en":"a newly built station","cn":"新建的车站"}],"base":"build"},"bump":{"oxford":{"phon":"bʌmp","pos":"verb","senses":[{"en":"to hit somebody/something by accident","cn":"（无意地）碰，撞","g":"[intransitive]","ex":{"en":"In the dark I bumped into a chair.","cn":"我在黑暗中撞上了一把椅子。"}},{"en":"to hit something, especially a part of your body, against or on something","cn":"（尤指身体部位）碰上，撞上","g":"[transitive]","ex":{"en":"Be careful not to bump your head on the beam when you stand up.","cn":"当心站起来时头别撞了横梁。"}},{"en":"to move across a rough surface","cn":"颠簸行进","g":"[intransitive, transitive]","ex":{"en":"The jeep bumped along the dirt track.","cn":"吉普车在土路上颠簸着行驶。"}},{"en":"to move somebody from one group or position to another; to remove somebody from a group","cn":"把（某人）调换到（另一群体或位置）；调出，开除出（某群体）","g":"[transitive]","ex":{"en":"The airline apologized and bumped us up to first class.","cn":"航空公司道歉后把我们调换到头等舱。"}},{"en":"the action or sound of something hitting a hard surface","cn":"碰撞（声）；撞击（声）","g":"[countable]","ex":{"en":"We could hear loud bumps from upstairs where the children were playing.","cn":"我们能听到孩子们在楼上嬉戏的乒乓声。"},"pos":"noun"},{"en":"a swelling (= an area that is larger and rounder than normal) on the body, often caused when you have been hit","cn":"肿块（常因击打所致）","g":"[countable]","ex":{"en":"She was covered in bumps and bruises.","cn":"她全身青肿，伤痕累累。"},"pos":"noun"},{"en":"the round shape of a woman’s stomach when she is pregnant","cn":"孕肚（孕妇腹部的隆起）","lab":"informal","ex":{"en":"She showed off her expanding bump in a black dress and cowboy boots.","cn":"她穿着黑色连衣裙和牛仔靴，展示了自己不断扩大的肚子。"},"pos":"noun"},{"en":"a part of a flat surface that is not even, but raised above the rest of it","cn":"隆起；凸块","g":"[countable]","lab":"figurative","ex":{"en":"a bump in the road","cn":"路面上的凸块"},"pos":"noun"},{"en":"a slight accident in which your vehicle hits something","cn":"轻微撞车事故","g":"[countable]","ex":{"en":"I had a bump in the car earlier, but it wasn’t serious.","cn":"我之前在车上碰了一下，但并不严重。"},"pos":"noun"},{"en":"(on a child’s birthday) the act of lifting the child in the air and then putting them down on the ground, once for every year of their age","cn":"生日举放仪式（在孩子生日时将其举高后再放在地上的仪式，举放次数与年龄相等）","g":"[plural]","lab":"British English","ex":{"en":"We gave her the bumps.","cn":"我们给她举行了生日举放仪式。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（无意地）碰撞，冲撞","en":"If you bump into something or someone, you accidentally hit them while you are moving.","ex":{"en":"They stopped walking and he almost bumped into them","cn":"他们停下了脚步，结果他差点儿撞到他们身上。"}},{"pos":"N-COUNT 可数名词","cn":"碰撞；碰撞声","en":"A bump is the action or the dull sound of two heavy objects hitting each other.","ex":{"en":"I felt a little bump and I knew instantly what had happened","cn":"我感觉到一点儿轻微的碰撞，便立刻意识到发生了什么。"}},{"pos":"N-COUNT 可数名词","cn":"（碰撞造成的）肿块，鼓包","en":"A bump is a minor injury or swelling that you get if you bump into something or if something hits you.","ex":{"en":"She fell against our coffee table and got a large bump on her forehead.","cn":"她倒地时撞到我们的咖啡桌上，额头起了个大包。"}},{"pos":"N-COUNT 可数名词","cn":"（车辆的）轻微碰撞","en":"If you have a bump while you are driving a car, you have a minor accident in which you hit something."},{"pos":"N-COUNT 可数名词","cn":"（地面的）隆起，凸块","en":"A bump on a road is a raised, uneven part.","ex":{"en":"The truck hit a bump and bounced.","cn":"卡车开过路面上的隆起处，颠了一下。"}},{"pos":"VERB 动词","cn":"颠簸而行","en":"If a vehicle bumps over a surface, it travels in a rough, bouncing way because the surface is very uneven.","ex":{"en":"We left the road, and again bumped over the mountainside","cn":"我们驶离公路，再次在山腰上颠簸前行。"}},{"pos":"PHRASE 短语","cn":"猛然回到现实中来","en":"If someone comes down to earth with a bump, they suddenly start recognizing unpleasant facts after a period of time when they have not been doing this.","ex":{"en":"Company bosses have come back down to earth with a bump after a period of post-election euphoria.","cn":"公司老板们在经历了一段选举过后的兴奋之后，重又回到现实中来。"}},{"pos":"","cn":"","en":"相关词组：bump into bump off bump up"}]},"media":{"uk":"media/uk/bump__gb_1.mp3","us":"media/us/bump__us_1.mp3"},"examples":[{"en":"If you are bumped off an airline because of overbooking, you are entitled to compensation.","cn":"假如机票超售而不能登机，你有权获得赔偿。"},{"en":"The airline apologized and bumped us up to first class.","cn":"航空公司道歉后把我们掉换到头等舱。"}]},"burger":{"media":{"uk":"media/uk/burger__gb_1.mp3","us":"media/us/burger__us_1.mp3"},"oxford":{"phon":"ˈbɜːɡə(r)","pos":"noun","senses":[{"en":"beef cut into small pieces and made into a flat round shape that is then fried, often served in a bread roll","cn":"汉堡包；汉堡牛肉饼","lab":"British English also"},{"en":"fish, vegetables, nuts, etc. cut into small pieces and made into flat round shapes like hamburgers","cn":"（鱼松、菜末、果仁等）汉堡饼","ex":{"en":"a spicy beanburger","cn":"香辣豆蓉饼"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"肉饼；汉堡包","en":"A burger is a flat round mass of minced meat or vegetables, which is fried and often eaten in a bread roll.","ex":{"en":"...burger and chips.","cn":"汉堡和薯条"}}]},"examples":[{"en":"a spicy beanburger","cn":"香辣豆蓉饼"}]},"bus":{"media":{"img":["media/pic/buses_comp.jpg","media/thumb/doubledecker.jpg"],"uk":"media/uk/bus__gb_1.mp3","us":"media/us/bus__us_1.mp3"},"oxford":{"phon":"bʌs","pos":"noun","senses":[{"en":"a large road vehicle that carries passengers, especially one that travels along a fixed route and stops regularly to let people get on and off","cn":"公共汽车；巴士","lab":"US English","ex":{"en":"Shall we walk or go by bus?","cn":"我们步行呢，还是坐公共汽车？"}},{"en":"a set of wires that carries information from one part of a computer system to another","cn":"（计算机系统的）总线","lab":"computing"},{"en":"to transport somebody by bus","cn":"用公共汽车运送","ex":{"en":"We were bussed from the airport to our hotel.","cn":"公共汽车把我们从机场送到旅馆。"},"pos":"verb"},{"en":"(in the US) to transport young people by bus to another area as a way of integrating schools (= having them educate black and white children together)","cn":"用校车送（学生往外区就读，使不同种族的学生一起受教育）","pos":"verb"},{"en":"to take the dirty plates, etc. off the tables in a restaurant, as a job","cn":"（在餐厅里）收（盘子），清理（桌子）","lab":"North American English","ex":{"en":"He buses tables to help finance his tuition.","cn":"他清理桌子来帮助支付学费。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公共汽车；巴士；大客车","en":"A bus is a large motor vehicle which carries passengers from one place to another. Buses drive along particular routes, and you have to pay to travel in them.","ex":{"en":"He missed his last bus home","cn":"他错过了回家的末班车。"}},{"pos":"V-ERG 及物/不及物动词","cn":"用大客车运送；乘坐公共汽车","en":"When someone is bussed to a particular place or when they bus there, they travel there on a bus.","ex":{"en":"On May Day hundreds of thousands used to be bussed in to parade through East Berlin","cn":"过去在五一劳动节这天，数十万人常常乘坐大巴到东柏林游行。"}},{"pos":"VERB 动词","cn":"用校车送","en":"In some parts of the United States, when children are bused to school, they are transported by bus to a school in a different area so that children of different races can be educated together.","ex":{"en":"Many schools were in danger of closing because the children were bused out to other neighborhoods.","cn":"很多学校面临倒闭的危险，因为学生被校车送到其他社区就读了。"}}]},"examples":[{"en":"A regular bus service connects the train station with the town centre.","cn":"火车站和市中心之间有定时班车。"},{"en":"We were bussed from the airport to our hotel.","cn":"公共汽车把我们从机场送到旅馆。"}]},"buck":{"media":{"uk":"media/uk/buck__gb_1.mp3","us":"media/us/buck__us_1.mp3"},"oxford":{"phon":"bʌk","pos":"noun","senses":[{"en":"a US, Australian or New Zealand dollar; a South African rand; an Indian rupee","cn":"（一）美元；（一）澳元；（一）新西兰元；（一）南非兰特；（一）印度卢比","g":"[countable]","lab":"informal","ex":{"en":"They cost ten bucks.","cn":"这些值十元钱。"}},{"en":"a male deer, hare or rabbit (also called a buck rabbit)","cn":"雄鹿；公兔","g":"[countable]"},{"en":"a deer, whether male or female","cn":"鹿（不论雌雄）","g":"[countable]","lab":"South African English","ex":{"en":"a herd of buck","cn":"一群鹿"}},{"en":"a young man","cn":"青年男子；小伙子","g":"[countable]","lab":"old use, informal，，"},{"en":"used in some expressions to refer to the responsibility or blame for something","cn":"（用于某些表达方式）责任，过失","g":"[singular]","ex":{"en":"It was my decision. The buck stops here (= nobody else can be blamed).","cn":"那是我的决定，不要追究别人了。"}},{"en":"to jump with the two back feet or all four feet off the ground","cn":"尥起后蹄跳跃；弓背四蹄跳起","g":"[intransitive]","ex":{"en":"The horse bucked wildly.","cn":"马猛烈地颠簸起来。"},"pos":"verb"},{"en":"to move up and down suddenly or in a way that lacks control","cn":"猛然震荡；剧烈颠簸","g":"[intransitive]","ex":{"en":"The boat bucked and heaved beneath them.","cn":"小船在他们脚下剧烈颠簸着。"},"pos":"verb"},{"en":"to resist or oppose something","cn":"抵制；反抗","g":"[transitive]","lab":"informal","ex":{"en":"One or two companies have managed to buck the trend of the recession.","cn":"有一两家公司顶住了经济滑坡的势头。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"美元；澳元","en":"A buck is a US or Australian dollar.","ex":{"en":"That would probably cost you about fifty bucks","cn":"那大概要花掉你50美元左右。"}},{"pos":"N-COUNT 可数名词","cn":"（雄鹿、公羚羊、公兔、雄袋鼠等）雄性动物","en":"A buck is the male of various animals, including the deer, antelope, rabbit and kangaroo."},{"pos":"N-COUNT 可数名词","cn":"（美洲印第安裔或非洲裔）小伙子","en":"A buck is a young Native American or African American man.","ex":{"en":"He'd been a real hell-raiser as a young buck.","cn":"他年轻时是个十足的捣蛋鬼。"}},{"pos":"ADJ 形容词","cn":"龅牙的","en":"If someone has buck teeth, their upper front teeth stick forward out of their mouth."},{"pos":"VERB 动词","cn":"（马）猛地弓背跃起，尥起后蹄跳跃","en":"If a horse bucks, it kicks both of its back legs wildly into the air, or jumps into the air wildly with all four feet off the ground.","ex":{"en":"The stallion bucked as he fought against the reins holding him tightly in.","cn":"牡马四蹄腾空跳起，想挣脱紧紧缚住它的缰绳。"}},{"pos":"VERB 动词","cn":"抵抗；抵制；反抗","en":"If you buck the trend, you obtain different results from others in the same area. If you buck the system, you get what you want by breaking or ignoring the rules.","ex":{"en":"While other newspapers are losing circulation, we are bucking the trend","cn":"当其他报纸的发行量越来越少时，我们却逆势而进。"}},{"pos":"PHRASE 短语","cn":"优厚的回报","en":"If you get more bang for the buck, you spend your money wisely and get more for your money than if you were to spend it in a different way.","ex":{"en":"I think it's very important for those governments to do whatever they can to get a bigger bang for the buck.","cn":"我认为，重要的是那些政府要采取一切措施来获取更大的资金回报。"}},{"pos":"PHRASE 短语","cn":"轻易赚来的钱；（常指）不义之财","en":"When someone makes a fast buck or makes a quick buck, they earn a lot of money quickly and easily, often by doing something which is considered to be dishonest.","ex":{"en":"His life isn't ruled by looking for a fast buck","cn":"他的生活没有被一味想发大财的心态左右。"}},{"pos":"PHRASE 短语","cn":"赚钱；挣钱","en":"If you are trying to make a buck, you are trying to earn some money.","ex":{"en":"The owners don't want to overlook any opportunity to make a buck.","cn":"老板们不想错过任何可以赚钱的机会。"}},{"pos":"PHRASE 短语","cn":"一丝不挂","en":"Someone who is buck naked is not wearing any clothes at all."},{"pos":"PHRASE 短语","cn":"推卸责任","en":"If you pass the buck, you refuse to accept responsibility for something, and say that someone else is responsible.","ex":{"en":"David says the responsibility is Mr Smith's and it's no good trying to pass the buck.","cn":"戴维说责任在史密斯先生，企图推脱责任是没有用的。"}},{"pos":"PHRASE 短语","cn":"责任止于此/应由…承担责任","en":"If you say 'The buck stops here' or 'The buck stops with me', you mean that you have to take responsibility for something and will not try to pass the responsibility on to someone else.","ex":{"en":"The buck stops with him. He is ultimately responsible for every aspect of the broadcast.","cn":"责任在于他。他是该广播节目各方面的总负责人。"}},{"pos":"","cn":"","en":"相关词组：buck for buck up"}]},"examples":[{"en":"One or two companies have managed to buck the trend of the recession.","cn":"有一两家公司顶住了经济滑坡的势头。"},{"en":"Buck up, kid! It's not the end of the game.","cn":"年轻人，振作起来！比赛还未结束呢。"}]},"burned":{"lemma":"burn"},"bulbs":{"lemma":"bulb"},"buddhist":{"media":{"uk":"media/uk/buddhist__gb_1.mp3","us":"media/us/buddhist__us_1.mp3"},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"佛教徒；佛门弟子","en":"A Buddhist is a person whose religion is Buddhism."},{"pos":"ADJ 形容词","cn":"佛教的；佛的","en":"Buddhist means relating or referring to Buddhism.","ex":{"en":"...Buddhist monks.","cn":"和尚"}}]},"examples":[{"en":"a Buddhist monk/temple","cn":"佛教僧侣/寺庙"},{"en":"a devout Buddhist","cn":"虔诚的佛教徒"}],"oxford":{"phon":"ˈbʊdɪst","pos":"adjective","senses":[{"en":"following or connected with the religion of Buddhism","cn":"佛教的;佛的","ex":{"en":"a Buddhist monk/temple","cn":"佛教僧侣／寺庙"}},{"en":"a person who follows the religion of Buddhism","cn":"佛教徒","ex":{"en":"a devout Buddhist","cn":"虔诚的佛教徒"},"pos":"noun"}]}},"bug":{"media":{"uk":"media/uk/bug__gb_1.mp3","us":"media/us/bug__us_1.mp3"},"oxford":{"phon":"bʌɡ","pos":"noun","senses":[{"en":"any small insect","cn":"小昆虫；虫子","g":"[countable]","lab":"especially North American English","ex":{"en":"There's a bug crawling up your arm.","cn":"有一只虫子爬上你的手臂。"}},{"en":"an illness that is usually fairly mild but spreads easily from person to person","cn":"轻微的传染病","g":"[countable]","lab":"informal","ex":{"en":"a flu bug","cn":"流感"}},{"en":"an enthusiastic interest in something such as a sport or a hobby","cn":"热衷；着迷","g":"[singular]","lab":"informal","ex":{"en":"She's been bitten by the travel bug.","cn":"她迷上了旅游。"}},{"en":"a fault in a machine, especially in a computer system or program","cn":"（机器，尤指计算机的）故障，程序错误，缺陷；隐错","g":"[countable]","ex":{"en":"The software is full of bugs.","cn":"这个软件有很多漏洞。"}},{"en":"a small hidden device for listening to other people’s conversations","cn":"窃听器","g":"[countable]","lab":"informal","ex":{"en":"They planted a bug in his hotel room.","cn":"他们在他的酒店房间里安了一个窃听器。"}},{"en":"to put a special device (= a bug) somewhere in order to listen secretly to other people’s conversations","cn":"在（某处）装窃听器；窃听（谈话）","ex":{"en":"They bugged her hotel room.","cn":"他们在她的旅馆房间里装了窃听器。"},"pos":"verb"},{"en":"to annoy somebody","cn":"激怒（某人）；招惹（某人）","lab":"informal","ex":{"en":"Stop bugging me!","cn":"别烦我了！"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小虫；臭虫","en":"A bug is an insect or similar small creature.","ex":{"en":"We noticed tiny bugs that were all over the walls.","cn":"我们注意到墙上爬满了小虫子。"}},{"pos":"N-COUNT 可数名词","cn":"小病；轻微的传染病","en":"A bug is an illness which is caused by small organisms such as bacteria.","ex":{"en":"I think I've got a bit of a stomach bug","cn":"我想我的胃可能出了点儿毛病。"}},{"pos":"N-COUNT 可数名词","cn":"（计算机程序中的）漏洞，错误，故障","en":"If there is a bug in a computer program, there is a mistake in it.","ex":{"en":"There is a bug in the software.","cn":"软件有漏洞。"}},{"pos":"N-COUNT 可数名词","cn":"（微型）窃听器","en":"A bug is a tiny hidden microphone which transmits what people are saying.","ex":{"en":"There was a bug on the phone.","cn":"电话装有窃听器。"}},{"pos":"VERB 动词","cn":"在…装窃听器","en":"If someone bugs a place, they hide tiny microphones in it which transmit what people are saying.","ex":{"en":"He heard that they were planning to bug his office","cn":"他得知他们打算在他办公室安装窃听器。"}},{"pos":"N-SING 单数名词","cn":"（对…的）热衷，迷恋","en":"You can say that someone has been bitten by a particular bug when they suddenly become very enthusiastic about something.","ex":{"en":"I've definitely been bitten by the gardening bug","cn":"我被园艺彻底迷住了。"}},{"pos":"VERB 动词","cn":"使烦恼；使厌烦","en":"If someone or something bugs you, they worry or annoy you.","ex":{"en":"I only did it to bug my parents.","cn":"我这么做只是为了让我父母心烦。"}}]},"examples":[{"en":"She was never interested in fitness before but now she's been bitten by the bug.","cn":"她以前从来不在乎健身，现在她却着了迷。"},{"en":"We should bug out now before it's too late.","cn":"我们现在就应该撤离，以免为时太晚。"}]},"bubbles":{"oxford":{"phon":"ˈbʌblz","pos":"","senses":[{"en":"a painting (1886) by Millais of his young grandson blowing soap bubbles. It is especially well known in Britain because it was bought by Pears, a soap company, who used it in their advertisements.","cn":"气泡：米莱（Millais）的一幅小孙子吹肥皂泡的画（1886年）。它在英国尤为著名，因为它是由肥皂公司Pears购买的，后者在广告中使用了它。"}]},"base":"bubble"},"bulletin":{"oxford":{"phon":"ˈbʊlətɪn","pos":"noun","senses":[{"en":"a short news report on the radio or television","cn":"（电台或电视台的）新闻简报","ex":{"en":"The story led the television news bulletins that evening.","cn":"这个故事成为当晚电视新闻的头条新闻。"}},{"en":"an official statement about something important","cn":"公告；布告","ex":{"en":"a bulletin on the president’s health","cn":"关于总统健康的公告"}},{"en":"a printed report that gives news about an organization or a group","cn":"（机构或组织的）简报","ex":{"en":"More details will be given in our next news bulletin.","cn":"在我们接下来的新闻简报中将有更详细的报道。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（电台或电视台的）简明新闻，简短消息，简讯","en":"A bulletin is a short news report on the radio or television.","ex":{"en":"...the early morning news bulletin.","cn":"早间新闻简报"}},{"pos":"N-COUNT 可数名词","cn":"公告；布告","en":"A bulletin is a short official announcement made publicly to inform people about an important matter.","ex":{"en":"At 3.30 p.m. a bulletin was released announcing that the president was out of immediate danger.","cn":"下午3点30分发布了公告，称总统已经暂时脱离危险。"}},{"pos":"N-COUNT 可数名词","cn":"（学校、教堂等机构或团体发放的）学报，会刊，小册子","en":"A bulletin is a regular newspaper or leaflet that is produced by an organization or group such as a school or church."}]},"media":{"uk":"media/uk/bulletin__gb_1.mp3","us":"media/us/bulletin__us_1.mp3"},"examples":[{"en":"a bulletin on the President's health","cn":"关于总统健康的公告"}]},"bunk":{"media":{"img":["media/pic/beds_comp.jpg","media/thumb/bunk.jpg"],"uk":"media/uk/bunk__gb_1.mp3","us":"media/us/bunk__us_1.mp3"},"oxford":{"phon":"bʌŋk","pos":"noun","senses":[{"en":"a narrow bed that is fixed to a wall, especially on a ship or train","cn":"（尤指船或火车的）卧铺","g":"[countable]"},{"en":"one of two beds that are fixed together, one above the other, especially for children","cn":"（尤指儿童的）双层床，架子床；上铺；下铺","g":"[countable]","ex":{"en":"I slept in the bottom bunk of a set of bunk beds.","cn":"我睡在一张双层床的下铺。"}},{"en":"ideas, statements or beliefs that you think are silly or not true","cn":"傻话；胡扯","g":"[uncountable]","lab":"old-fashioned, informal，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指船上或车上的）铺位，卧铺","en":"A bunk is a bed that is fixed to a wall, especially in a ship or caravan.","ex":{"en":"He left his bunk and went up on deck again.","cn":"他离开自己的铺位再次走到甲板上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"胡说；谎言","en":"If you describe something as bunk, you think that it is foolish or untrue.","ex":{"en":"...Henry Ford's opinion that 'history is bunk'.","cn":"亨利·福特认为“历史都是谎言”的观点"}},{"pos":"PHRASE 短语","cn":"不辞而别；溜走","en":"If you do a bunk, you suddenly leave a place without telling anyone."},{"pos":"","cn":"","en":"相关词组：bunk off"}]},"examples":[{"en":"What a load of bunk!","cn":"一派胡言！"},{"en":"You can bunk down on the sofa for tonight.","cn":"今天晚上你可以睡在沙发上。"}]},"buffered":{"lemma":"buffer","media":{"uk":"media/uk/buffer__gb_1.mp3","us":"media/us/buffer__us_1.mp3"}},"burst":{"media":{"uk":"media/uk/burst__gb_1.mp3","us":"media/us/burst__us_1.mp3"},"oxford":{"phon":"bɜːst","pos":"verb","senses":[{"en":"to break open or apart, especially because of pressure from inside; to make something break in this way","cn":"（使）爆裂，胀开","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"That balloon will burst if you blow it up any more.","cn":"你再给气球充气，它就要爆了。"}},{"en":"to go or move somewhere suddenly with great force; to come from somewhere suddenly","cn":"猛冲；突然出现","g":"[intransitive]","ex":{"en":"He burst into the room without knocking.","cn":"他没敲门就闯进了屋子。"}},{"en":"to be very full of something; to be very full and almost breaking open","cn":"爆满；涨满","g":"[intransitive]","lab":"informal","ex":{"en":"The roads are bursting with cars.","cn":"那些路上挤满了车。"}},{"en":"a short period of a particular activity or strong emotion that often starts suddenly","cn":"突发；猝发；迸发；爆破","ex":{"en":"a sudden burst of activity/energy/laughter","cn":"突然热闹起来；迸发出能量／笑声"},"pos":"noun"},{"en":"an occasion when something bursts; the hole left where something has burst","cn":"爆裂；裂口","ex":{"en":"a burst in a water pipe","cn":"水管上的裂缝"},"pos":"noun"},{"en":"a short series of shots from a gun","cn":"一阵短促的射击","ex":{"en":"frequent bursts of machine-gun fire","cn":"机枪的频频扫射"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）爆裂；（使）胀破；（使）炸开","en":"If something bursts or if you burst it, it suddenly breaks open or splits open and the air or other substance inside it comes out.","ex":{"en":"The driver lost control when a tyre burst","cn":"一个车胎爆了，司机失去了控制。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）破裂","en":"If a dam bursts, or if something bursts it, it breaks apart because the force of the river is too great.","ex":{"en":"A dam burst and flooded their villages.","cn":"堤坝决口，淹没了他们的村庄。"}},{"pos":"VERB 动词","cn":"（河流）决堤","en":"If a river bursts its banks, the water rises and goes on to the land.","ex":{"en":"Monsoons caused the river to burst its banks.","cn":"季风雨使河堤决口。"}},{"pos":"VERB 动词","cn":"（门、盖子等）猛然打开","en":"When a door or lid bursts open, it opens very suddenly and violently because someone pushes it or there is great pressure behind it.","ex":{"en":"The door burst open and an angry young nurse appeared.","cn":"门突然被推开，一名怒气冲冲的年轻护士出现在门口。"}},{"pos":"VERB 动词","cn":"突然闯进（或跑出）","en":"To burst into or out of a place means to enter or leave it suddenly with a lot of energy or force.","ex":{"en":"Gunmen burst into his home and opened fire","cn":"持枪歹徒突然闯进他家里开枪射击。"}},{"pos":"VERB 动词","cn":"突然出现","en":"If you say that something bursts onto the scene, you mean that it suddenly starts or becomes active, usually after developing quietly for some time.","ex":{"en":"He burst onto the fashion scene in the early 1980s.","cn":"20世纪80年代初他突然在时尚界活跃起来。"}},{"pos":"VERB 动词","cn":"充满；满怀","en":"If you say that someone is about to burst with pride, anger, or another emotion, you are emphasizing the intensity of the emotion they are feeling.","ex":{"en":"He almost burst with pride when his son John began to excel at football","cn":"当儿子约翰在足球方面表现优秀时，他心中充满了自豪。"}},{"pos":"VERB 动词","cn":"爆炸","en":"When a firework or bomb bursts in the air, it explodes.","ex":{"en":"Hundreds of fireworks burst simultaneously in midair","cn":"成百上千朵烟花在半空中同时绽放。"}},{"pos":"N-COUNT 可数名词","cn":"短暂的突然发作;一阵","en":"A burst of something is a sudden short period of it.","ex":{"en":"...a burst of machine-gun fire","cn":"一阵炮火"}},{"pos":"","cn":"","en":"相关词组：burst into burst out"}]},"examples":[{"en":"Firefighters burst the door open and rescued them.","cn":"消防队员撞开门，把他们救了出来。"},{"en":"I tend to work in bursts.","cn":"我的工作劲头往往是一阵一阵的。"}]},"butt":{"oxford":{"phon":"bʌt","pos":"verb","senses":[{"en":"to hit or push somebody/something hard with your head","cn":"（人）用头顶撞"},{"en":"if an animal butts somebody/something, it hits them or it hard with its horns and head","cn":"（动物）用头（或角）顶"},{"en":"the thick end of a weapon or tool","cn":"（武器或工具的）粗大的一端","ex":{"en":"a rifle butt","cn":"步枪的枪托"},"pos":"noun"},{"en":"the part of a cigarette or cigar that is left after it has been smoked","cn":"烟蒂；烟头","ex":{"en":"an ashtray full of cigarette butts","cn":"满是烟头的烟灰缸。"},"pos":"noun"},{"en":"a large round container for storing or collecting liquids","cn":"（盛液体的）大桶","lab":"British English","ex":{"en":"a water butt","cn":"集雨桶"},"pos":"noun"},{"en":"the part of the body that you sit on","cn":"屁股","lab":"especially North American English, informal，，","ex":{"en":"Get off your butt and do some work!","cn":"起来干点活儿吧！"},"pos":"noun"},{"en":"the act of hitting somebody with your head","cn":"（头的）顶撞","ex":{"en":"a butt from his head","cn":"被他的头撞的一下"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"屁股","en":"Someone's butt is their bottom.","ex":{"en":"Frieda grinned, pinching him on the butt.","cn":"弗里达咧嘴笑了，捏了捏他的屁股。"}},{"pos":"N-COUNT 可数名词","cn":"（武器或工具）较粗的一端，柄","en":"The butt or the butt end of a weapon or tool is the thick end of its handle.","ex":{"en":"Troops used tear gas and rifle butts to break up the protests","cn":"军队使用催泪瓦斯和枪托驱散示威者。"}},{"pos":"N-COUNT 可数名词","cn":"烟蒂；烟头","en":"The butt of a cigarette or cigar is the small part of it that is left when someone has finished smoking it.","ex":{"en":"He dropped his cigarette butt into the street below","cn":"他把烟头扔到下面的街道上。"}},{"pos":"N-COUNT 可数名词","cn":"（装液体用的）大桶","en":"A butt is a large barrel used for collecting or storing liquid."},{"pos":"N-SING 单数名词","cn":"（嘲笑或批评的）对象，笑柄","en":"If someone or something is the butt of jokes or criticism, people often make fun of them or criticize them.","ex":{"en":"He is still the butt of cruel jokes about his humble origins.","cn":"他仍然因出身低微而被人无情嘲笑。"}},{"pos":"VERB 动词","cn":"（用头）顶，撞","en":"If a person or animal butts you, they hit you with the top of their head.","ex":{"en":"Lawrence kept on butting me but the referee did not warn him.","cn":"劳伦斯不停地用头撞我，但是裁判并没有警告他。"}},{"pos":"","cn":"","en":"相关词组：butt in butt out"}]},"media":{"uk":"media/uk/butt__gb_1.mp3","us":"media/us/butt__us_1.mp3"},"examples":[{"en":"‘Is that normal?’ Josie butted in. “","cn":"那是正常的吗？”乔西插了一句。"},{"en":"Butt out, Neil! This is none of your business.","cn":"不许插手，尼尔！这不关你的事。"}]},"bulky":{"media":{"uk":"media/uk/bulky__gb_1.mp3","us":"media/us/bulky__us_1.mp3"},"oxford":{"phon":"ˈbʌlki","pos":"adjective","senses":[{"en":"large and difficult to move or carry","cn":"庞大的；笨重的","ex":{"en":"Bulky items will be collected separately.","cn":"大件物品将分开收集。"}},{"en":"tall and heavy","cn":"大块头的；高大肥胖的","ex":{"en":"The bulky figure of Inspector Jones appeared at the door.","cn":"琼斯督察的壮硕身躯出现在门口。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"庞大的；笨重的","en":"Something that is bulky is large and heavy. Bulky things are often difficult to move or deal with.","ex":{"en":"...bulky items like lawn mowers.","cn":"割草机之类的庞大物件"}}]},"examples":[{"en":"The bulky figure of Inspector Jones appeared at the door.","cn":"琼斯督察的壮硕身躯出现在门口。"},{"en":"Bulky items will be collected separately.","cn":"大件物品将分开收集。"}]},"burn":{"oxford":{"phon":"bɜːn","pos":"verb","senses":[{"en":"to produce flames and heat","cn":"燃烧；烧","g":"[intransitive]","sc":"fire","ex":{"en":"A welcoming fire was burning in the fireplace.","cn":"壁炉里燃烧着暖融融的炉火。"}},{"en":"to be on fire","cn":"着火；烧着","g":"[intransitive]","sc":"fire","ex":{"en":"By nightfall the whole city was burning.","cn":"到黄昏时，全城已是一片火海。"}},{"en":"to destroy, damage, injure or kill somebody/something by fire; to be destroyed, etc. by fire","cn":"（使）烧毁，烧坏，烧伤，烧死","g":"[transitive, intransitive]","sc":"fire","ex":{"en":"Six million acres have burned this year in the United States.","cn":"美国今年已烧毁 600 万英亩土地。"}},{"en":"if you burn a fuel, or a fuel burns, it produces heat, light or energy","cn":"（使燃料）燃烧","g":"[transitive, intransitive]","lab":"figurative","sc":"fuel","ex":{"en":"Which fuel burns most efficiently?","cn":"哪种燃料燃烧效果最佳？"}},{"en":"if food burns, or if you burn it, it is damaged by too much heat","cn":"（使）烧焦，烤煳","g":"[intransitive, transitive]","sc":"food","ex":{"en":"I can smell something burning in the kitchen.","cn":"我闻到厨房里有东西烧焦了。"}},{"en":"to be damaged or injured by the sun, heat, acid, etc.; to damage or injure somebody/something in this way","cn":"（使）晒伤，烫伤，烧伤","g":"[intransitive, transitive]","sc":"sun/heat","ex":{"en":"My skin burns easily (= in the sun).","cn":"我的皮肤容易晒伤。"}},{"en":"if part of your body burns or is burning, it feels very hot and painful","cn":"火辣辣地痛；发烫","g":"[intransitive]","sc":"of part of body","ex":{"en":"Your forehead's burning. Have you got a fever?","cn":"你的前额很烫，你发烧了吗？"}},{"en":"to produce light","cn":"发光；发亮","g":"[intransitive]","sc":"of a light","ex":{"en":"Lights were burning upstairs, but no one answered the door.","cn":"楼上亮着灯，但叫门没人回应。"}},{"en":"to feel or show a very strong emotion or desire","cn":"有强烈的情感；渴望","g":"[intransitive, transitive]","lab":"literary","sc":"feel emotion/desire","ex":{"en":"Her eyes burned fiercely.","cn":"她的眼睛燃烧着怒火。"}},{"en":"to move very fast in a particular direction","cn":"飞奔；疾驰","g":"[intransitive]","lab":"informal","sc":"go fast","ex":{"en":"The car was burning down the road.","cn":"汽车沿着公路疾驰而去。"}},{"en":"to make somebody very angry","cn":"激怒；使大怒","g":"[transitive]","lab":"North American English, informal，，","sc":"make angry","ex":{"en":"So you did it just to burn me?","cn":"这么说，你那样做只是为了气我？"}},{"en":"to put information onto a CD or DVD","cn":"刻录（光盘或数字影碟）","g":"[transitive, intransitive]","sc":"CD, DVD"},{"en":"to spend money","cn":"花钱","g":"[transitive, intransitive]","lab":"business, informal，，","sc":"spend money","ex":{"en":"The project burns £2 million a year in contractor costs.","cn":"这个项目每年要花掉 200 万英镑的承包商费用。"}},{"en":"an injury or a mark caused by fire, heat or acid","cn":"烧伤；烫伤；灼伤；烧（或烫、灼）的痕迹","g":"[countable]","sc":"injury","ex":{"en":"to have minor/severe/third-degree burns","cn":"受到轻度／重度／三度烧伤"},"pos":"noun"},{"en":"the feeling that you get in your muscles when you have done a lot of exercise","cn":"酸痛感","g":"[singular]","sc":"in muscles","ex":{"en":"Feel the burn!","cn":"感受灼烧感！"},"pos":"noun"},{"en":"a small river","cn":"小河；溪流","g":"[countable]","lab":"Scottish English","sc":"river","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"着火；燃烧","en":"If there is a fire or a flame somewhere, you say that there is a fire or flame burning there.","ex":{"en":"Fires were burning out of control in the center of the city","cn":"市中心的火势失去了控制。"}},{"pos":"VERB 动词","cn":"着火；烧着","en":"If something is burning, it is on fire.","ex":{"en":"When I arrived one of the vehicles was still burning.","cn":"当我到达时，其中一辆车还在燃烧。"}},{"pos":"VERB 动词","cn":"烧掉；烧毁","en":"If you burn something, you destroy or damage it with fire.","ex":{"en":"Protesters set cars on fire and burned a building","cn":"抗议者焚烧汽车，并烧毁了一座建筑。"}},{"pos":"V-ERG 及物/不及物动词","cn":"点燃；燃烧","en":"If you burn a fuel or if it burns, it is used to produce heat, light, or energy.","ex":{"en":"The power stations burn coal from the Ruhr region","cn":"发电站烧的煤产自鲁尔地区。"}},{"pos":"V-ERG 及物/不及物动词","cn":"烧焦；烤煳","en":"If you burn something that you are cooking or if it burns, you spoil it by using too much heat or cooking it for too long.","ex":{"en":"I burnt the toast","cn":"我把面包烤糊了。"}},{"pos":"VERB 动词","cn":"烧伤；灼伤","en":"If you burn part of your body, burn yourself, or are burnt, you are injured by fire or by something very hot.","ex":{"en":"Take care not to burn your fingers","cn":"注意别烧着手指头。"}},{"pos":"VERB 动词","cn":"烧死","en":"If someone is burnt or burnt to death, they are killed by fire.","ex":{"en":"Women were burned as witches in the middle ages","cn":"妇女在中世纪时被当成女巫烧死。"}},{"pos":"VERB 动词","cn":"发光；照亮","en":"If a light is burning, it is shining.","ex":{"en":"The building was darkened except for a single light burning in a third-story window.","cn":"整座大楼一片漆黑，只有3层的一个窗户透出一丝光亮。"}},{"pos":"VERB 动词","cn":"（因尴尬或心烦而）脸红","en":"If your face is burning, it is red because you are embarrassed or upset.","ex":{"en":"Liz's face was burning.","cn":"利兹的脸红得发烫。"}},{"pos":"VERB 动词","cn":"有强烈的情感；极度渴望","en":"If you are burning with an emotion or are burning to do something, you feel that emotion or the desire to do that thing very strongly.","ex":{"en":"The young boy was burning with a fierce ambition","cn":"这个年轻人怀有极其远大的抱负。"}},{"pos":"V-ERG 及物/不及物动词","cn":"晒伤；晒黑","en":"If you burn or get burned in the sun, the sun makes your skin become red and sore.","ex":{"en":"Build up your tan slowly and don't allow your skin to burn","cn":"慢慢地将皮肤晒成古铜色，小心别让太阳把皮肤晒伤。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）火辣辣地痛；（使）发烫","en":"If a part of your body burns or if something burns it, it has a painful, hot or stinging feeling.","ex":{"en":"My eyes burn from staring at the needle","cn":"我的眼睛由于长时间盯着针看而疼痛。"}},{"pos":"VERB 动词","cn":"遭受损失；亏损","en":"If you are burned or get burned, you lose something as a result of taking a risk, usually in a business deal.","ex":{"en":"They always took chances and got burned very badly in past years.","cn":"他们总是冒险，在过去的几年里损失惨重。"}},{"pos":"VERB 动词","cn":"刻录（光盘）","en":"To burn a CD-ROM means to write or copy data onto it.","ex":{"en":"You can use this software to burn custom compilations of your favorite tunes.","cn":"你可以用这个软件来刻录你最喜欢的乐曲。"}},{"pos":"","cn":"","en":"to burn the candle at both ends→see: ; to get your fingers burned→see: ; to burn something to the ground→see: ; to burn the midnight oil→see: ; to have money to burn→see: ;"},{"pos":"","cn":"","en":"相关词组：burn down burn off burn out burn up"}]},"media":{"uk":"media/uk/burn__gb_1.mp3","us":"media/us/burn__us_1.mp3"},"examples":[{"en":"By the age of 25 she was completely burned out and retired from the sport.","cn":"她到 25 岁时就已体力耗尽，退出了体坛。"},{"en":"He got his fingers badly burnt dabbling in the stock market.","cn":"他糊里糊涂地进入股票市场，结果赔了老本。"}]},"buried":{"lemma":"bury"},"bureau":{"media":{"uk":"media/uk/bureau__gb_1.mp3","us":"media/us/bureau__us_1.mp3"},"oxford":{"phon":"ˈbjʊərəʊ","pos":"noun","senses":[{"en":"a desk with drawers and usually a top that opens down to make a table to write on","cn":"（附抽屉及活动写字台的）书桌","lab":"British English","ex":{"en":"There was just enough space for a fold-up bed, washstand and bureau.","cn":"仅仅够空间放下一张折叠床、一个洗手台和斗柜。"}},{"en":"a piece of furniture with drawers (= parts like boxes built into it with handles on the front for pulling them out) for keeping clothes in","cn":"五斗橱；（有抽屉的）衣橱","lab":"both North American English"},{"en":"an office or organization that provides information on a particular subject","cn":"（提供某方面信息的）办事处，办公室，机构","lab":"especially North American English","ex":{"en":"She works for an employment bureau.","cn":"她在一家职业介绍所工作。"}},{"en":"(in the US) a government department or part of a government department","cn":"（美国政府部门）局，处，科","ex":{"en":"the Federal Bureau of Investigation","cn":"联邦调查局"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"（政府或组织机构的）局，所，司，处，属","en":"A bureau is an office, organization, or government department that collects and distributes information.","ex":{"en":"...the Federal Bureau of Investigation.","cn":"联邦调查局"}},{"pos":"N-COUNT 可数名词","cn":"办事处；分公司","en":"A bureau is an office of a company or organization which has its main office in another town or country.","ex":{"en":"...the Wall Street Journal's Washington bureau.","cn":"《华尔街日报》华盛顿分社"}},{"pos":"N-COUNT 可数名词","cn":"书桌;写字台","en":"A bureau is a writing desk with shelves and drawers and a lid that opens to form the writing surface."},{"pos":"N-COUNT 可数名词","cn":"五斗橱；衣柜","en":"A bureau is a chest of drawers."}]},"examples":[{"en":"an employment bureau","cn":"职业介绍所"},{"en":"the Federal Bureau of Investigation","cn":"联邦调查局"}]},"bulb":{"oxford":{"phon":"bʌlb","pos":"noun","senses":[{"en":"the glass part that fits into an electric lamp, etc. to give light when it is switched on","cn":"电灯泡","ex":{"en":"a halogen bulb","cn":"卤素灯泡"}},{"en":"the round underground part of some plants, like an onion in shape, that grows into a new plant every year","cn":"（植物）鳞茎","ex":{"en":"the bulb fields of Holland","cn":"荷兰的郁金香花田"}},{"en":"an object that is like a bulb in shape, for example the end of a thermometer","cn":"鳞茎状物（如温度计的球部）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"电灯泡","en":"A bulb is the glass part of an electric lamp, which gives out light when electricity passes through it.","ex":{"en":"The stairwell was lit by a single bulb.","cn":"楼梯间只有一盏灯照明。"}},{"pos":"N-COUNT 可数名词","cn":"球茎；鳞茎","en":"A bulb is a root shaped like an onion that grows into a flower or plant.","ex":{"en":"...tulip bulbs.","cn":"郁金香球茎"}}]},"media":{"uk":"media/uk/bulb__gb_1.mp3","us":"media/us/bulb__us_1.mp3","img":["media/ldoce/img/bulb.jpg"]},"examples":[{"en":"a room lit by bare bulbs (= with no decorative cover)","cn":"只有光秃秃的电灯泡照明的屋子（无灯罩、灯饰）"},{"en":"a 60-watt bulb * 60","cn":"瓦的灯泡"}]},"butler":{"oxford":{"phon":"ˈbʌtlə(r)","pos":"noun","senses":[{"en":"the main male servant in a large house","cn":"男管家","ex":{"en":"The butler announced that dinner was served.","cn":"管家通报说晚餐端上桌了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男管家；男仆役长","en":"A butler is the most important male servant in a wealthy house."}]},"media":{"uk":"media/uk/butler__gb_1.mp3","us":"media/us/butler__us_1.mp3"}},"bustle":{"oxford":{"phon":"ˈbʌsl","pos":"verb","senses":[{"en":"to move around in a busy way or to hurry somebody in a particular direction","cn":"四下忙碌；催促（某人向某方向）","ex":{"en":"She bustled around in the kitchen.","cn":"她在厨房里忙得团团转。"}},{"en":"busy and noisy activity","cn":"忙乱嘈杂；喧闹","g":"[uncountable]","ex":{"en":"the hustle and bustle of city life","cn":"都市生活的喧闹繁忙"},"pos":"noun"},{"en":"a frame that was worn under a skirt by women in the past in order to hold the skirt out at the back","cn":"（旧时女子用的）裙撑","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"忙碌；奔忙","en":"If someone bustles somewhere, they move there in a hurried way, often because they are very busy.","ex":{"en":"My mother bustled around the kitchen","cn":"我母亲在厨房忙得团团转。"}},{"pos":"VERB 动词","cn":"繁忙；活跃","en":"A place that is bustling with people or activity is full of people who are very busy or lively.","ex":{"en":"The sidewalks are bustling with people","cn":"人行道上的行人熙熙攘攘。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"繁忙；喧闹","en":"Bustle is busy, noisy activity.","ex":{"en":"...the hustle and bustle of modern life","cn":"现代生活的拥挤喧嚣"}}]},"media":{"uk":"media/uk/bustle__gb_1.mp3","us":"media/us/bustle__us_1.mp3"},"examples":[{"en":"She bustled around in the kitchen.","cn":"她在厨房里忙得团团转。"},{"en":"The nurse bustled us out of the room.","cn":"护士催促我们离开房间。"}]},"built-in":{"oxford":{"phon":"ˌbɪlt ˈɪn","pos":"adjective","senses":[{"en":"included as part of something and not separate from it","cn":"是…的组成部分的；嵌入式的；内置的","lab":"British English","ex":{"en":"Both bedrooms have built-in wardrobes.","cn":"两个卧室都有嵌入式衣柜。"}},{"en":"existing as an essential part of something","cn":"是…的组成部分的；嵌入式的；内置的","lab":"more frequent","ex":{"en":"The system has a built-in resistance to change.","cn":"这个体制本身固有一种拒绝改变的特性。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"内置的；嵌入式的","en":"Built-in devices or features are included in something as a part of it, rather than being separate.","ex":{"en":"...modern cameras with built-in flash units","cn":"有内置闪光灯的新式相机"}}]},"media":{"uk":"media/uk/built_in_1_gb_1.mp3","us":"media/us/built_in_1_us_1.mp3"},"examples":[{"en":"built-in cupboards","cn":"壁橱"},{"en":"a built-in microphone","cn":"内置麦克风"}]},"butter":{"oxford":{"phon":"ˈbʌtə(r)","pos":"noun","senses":[{"en":"a soft yellow food made from cream, used in cooking and for spreading on bread","cn":"黄油；奶油","lab":"North American English","ex":{"en":"Fry the onions in butter.","cn":"用黄油炒洋葱。"}},{"en":"to spread butter on something","cn":"涂黄油于","ex":{"en":"She buttered four thick slices of bread.","cn":"她用黄油涂了四片厚面包。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"黄油；牛油","en":"Butter is a soft yellow substance made from cream. You spread it on bread or use it in cooking.","ex":{"en":"...bread and butter","cn":"面包和黄油"}},{"pos":"VERB 动词","cn":"给…抹上黄油；涂黄油于","en":"If you butter something such as bread or toast, you spread butter on it.","ex":{"en":"She spread pieces of bread on the counter and began buttering them.","cn":"她把几片面包摆在台上，开始抹黄油。"}},{"pos":"PHRASE 短语","cn":"明白自己的利益所在；善于为自己打算","en":"If you say that someone knows what side their bread is buttered on, you mean that they know what to do or who to please in order to stay in a good situation or to avoid a bad one.","ex":{"en":"These chaps know what side their bread's buttered on.","cn":"这些家伙知道怎样做对他们有利。"}},{"pos":"","cn":"","en":"相关词组：butter up"}]},"media":{"uk":"media/uk/butter__gb_1.mp3","us":"media/us/butter__us_1.mp3"},"examples":[{"en":"She buttered four thick slices of bread.","cn":"她用黄油涂了四片厚面包。"},{"en":"Fry the onions in butter.","cn":"用黄油炒洋葱。"}]},"business":{"media":{"uk":"media/uk/business__gb_1.mp3","us":"media/us/business__us_1.mp3"},"oxford":{"phon":"ˈbɪznəs","pos":"noun","senses":[{"en":"the activity of making, buying, selling or supplying goods or services for money","cn":"商业；买卖；生意","g":"[uncountable, singular]","sc":"trade","ex":{"en":"It's been a pleasure to do business with you.","cn":"和你做买卖很愉快。"}},{"en":"work that is part of your job","cn":"商务；公事","g":"[uncountable]","sc":"work","ex":{"en":"Is the trip to Rome for business or pleasure?","cn":"这次去罗马是公干还是游玩？"}},{"en":"the amount of work done by a company, etc.; the rate or quality of this work","cn":"营业额；贸易额","g":"[uncountable]","sc":"work","ex":{"en":"Business is booming.","cn":"生意兴隆。"}},{"en":"a commercial organization such as a company, shop or factory","cn":"商业机构；企业；公司；商店；工厂","g":"[countable]","lab":"North American English","sc":"company","ex":{"en":"an organization that represents small businesses","cn":"代表小企业的组织"}},{"en":"something that a particular person or organization is responsible for","cn":"归（某人或某机构）管的事；职责","g":"[uncountable]","sc":"responsibility","ex":{"en":"It is the business of the police to protect the community.","cn":"警察的职责是保护社会。"}},{"en":"important matters that need to be dealt with or discussed","cn":"（需要处理或讨论的）重要事情，要点","g":"[uncountable]","sc":"important matters","ex":{"en":"He has some unfinished business to deal with.","cn":"他还要处理一些尚未了结的事务。"}},{"en":"a matter, an event or a situation","cn":"事情；事件；状况","g":"[singular]","sc":"event","ex":{"en":"That plane crash was a terrible business.","cn":"那次飞机坠毁是十分可怕的事。"}},{"en":"the fact of a person or people buying goods or services at a shop or business","cn":"（顾客对商店的）惠顾，光顾","g":"[uncountable]","lab":"especially North American English","sc":"being a customer","ex":{"en":"We're grateful for your business.","cn":"感谢您光顾本店。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"商业；买卖；交易；生意","en":"Business is work relating to the production, buying, and selling of goods or services.","ex":{"en":"...young people seeking a career in business","cn":"涉足商界的年轻人"}},{"pos":"N-UNCOUNT 不可数名词","cn":"业务量；营业额","en":"Business is used when talking about how many products or services a company is able to sell. If business is good, a lot of products or services are being sold and if business is bad, few of them are being sold.","ex":{"en":"They worried that German companies would lose business","cn":"他们担心德国公司的业务量会下滑。"}},{"pos":"N-COUNT 可数名词","cn":"工商企业；公司；商店；商铺","en":"A business is an organization which produces and sells goods or which provides a service.","ex":{"en":"The company was a family business","cn":"这家公司是个家族企业。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"任务；职责；工作","en":"Business is work or some other activity that you do as part of your job and not for pleasure.","ex":{"en":"I'm here on business","cn":"我到这儿来办公事。"}},{"pos":"N-SING 单数名词","cn":"行业；（某一领域的）工作","en":"You can use business to refer to a particular area of work or activity in which the aim is to make a profit.","ex":{"en":"May I ask you what business you're in?","cn":"我可否问问你是做什么工作的？"}},{"pos":"N-SING 单数名词","cn":"眼前所做之事；手头的事","en":"You can use business to refer to something that you are doing or concerning yourself with.","ex":{"en":"...recording Ben as he goes about his business","cn":"录下本在处理事务时的镜头片断"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（需要处理的）重要事情，要点","en":"You can use business to refer to important matters that you have to deal with.","ex":{"en":"The most important business was left to the last","cn":"最重要的事留到最后来解决。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"个人的事；私事","en":"If you say that something is your business, you mean that it concerns you personally and that other people have no right to ask questions about it or disagree with it.","ex":{"en":"My sex life is my business","cn":"我的性生活是我自己的事。"}},{"pos":"N-SING 单数名词","cn":"事件；情况；活动","en":"You can use business to refer in a general way to an event, situation, or activity. For example, you can say something is 'a wretched business' or you can refer to 'this assassination business'.","ex":{"en":"We have sorted out this wretched business at last","cn":"我们最终还是把这件破事儿理顺了。"}},{"pos":"N-SING 单数名词","cn":"（令人不快或耗费钱财的）活儿，事情","en":"You can use business when describing a task that is unpleasant in some way. For example, if you say that doing something is a costly business, you mean that it costs a lot.","ex":{"en":"Coastal defence is a costly business","cn":"海防事务很耗费资财。"}},{"pos":"PHR-RECIP 相互短语","cn":"做买卖；做生意","en":"If two people or companies do business with each other, one sells goods or services to the other.","ex":{"en":"I was fascinated by the different people who did business with me.","cn":"我对那些跟我做生意的形形色色的人非常感兴趣。"}},{"pos":"PHRASE 短语","cn":"无权；没有理由","en":"If you say that someone has no business to be in a place or to do something, you mean that they have no right to be there or to do it.","ex":{"en":"Really I had no business to be there at all.","cn":"真的，我根本没有道理呆在那里。"}},{"pos":"PHRASE 短语","cn":"在经营中","en":"A company that is in business is operating and trading.","ex":{"en":"You can't stay in business without cash.","cn":"没有现金，你无法运营。"}},{"pos":"PHRASE 短语","cn":"万事俱备","en":"If you say you are in business, you mean you have everything you need to start something immediately.","ex":{"en":"All you need is a microphone, and you're in business.","cn":"再来一只麦克风，你就万事俱备了。"}},{"pos":"PHRASE 短语","cn":"当真的；严肃的","en":"If you say that someone means business, you mean they are serious and determined about what they are doing.","ex":{"en":"Now people are starting to realise that he means business.","cn":"人们现在才开始明白他不是在开玩笑。"}},{"pos":"PHRASE 短语","cn":"没你的事；少管闲事","en":"If you say to someone 'mind your own business' or 'it's none of your business', you are rudely telling them not to ask about something that does not concern them.","ex":{"en":"I asked Laura what was wrong and she told me to mind my own business.","cn":"我问劳拉发生了什么事，她让我少管闲事。"}},{"pos":"PHRASE 短语","cn":"决定做","en":"If you make it your business to do something, you decide to do it, because you are interested in it or because you want to find out something.","ex":{"en":"She made it her business to find out.","cn":"她决定要查明真相。"}},{"pos":"PHRASE 短语","cn":"是不会（做）…的；才不会（做）","en":"If you say that you are not in the business of doing something, you are emphasizing that you do not do it, usually when you are annoyed or surprised that someone thinks you do.","ex":{"en":"We are not in the business of subsidising scroungers.","cn":"我们是不会资助那些乞丐的。"}},{"pos":"PHRASE 短语","cn":"停业；破产","en":"If a shop or company goes out of business or is put out of business, it has to stop trading because it is not making enough money.","ex":{"en":"Thousands of firms could go out of business.","cn":"成千上万个企业可能破产。"}},{"pos":"PHRASE 短语","cn":"同类中最好的","en":"If you say that someone or something is the business, you mean that they are the best of their kind.","ex":{"en":"When you watch him in training, you realise that this lad is the business.","cn":"当你观看他训练时，你就会意识到这个小伙子是最棒的。"}},{"pos":"PHRASE 短语","cn":"一切如常；处之泰然","en":"In a difficult situation, if you say it is business as usual, you mean that people will continue doing what they normally do.","ex":{"en":"The Queen was determined to show it was business as usual.","cn":"女王决定表现出一切正常的样子。"}}]},"examples":[{"en":"I think we've finished item four. Now is there any other business?","cn":"我想我们已经讨论完第四项。还有其他要讨论的吗？"},{"en":"All we need is a car and we'll be in business.","cn":"我们所需要的只是一辆车，然后我们就准备就绪了。"}]},"buffer":{"oxford":{"phon":"ˈbʌfə(r)","pos":"noun","senses":[{"en":"a thing or person that reduces a shock or protects somebody/something against difficulties","cn":"缓冲物；起缓冲作用的人","ex":{"en":"Support from family and friends acts as a buffer against stress.","cn":"家庭和朋友的支持有助于减缓压力。"}},{"en":"one of two round metal devices on the front or end of a train, or at the end of a railway track, that reduce the shock if the train hits something","cn":"（火车头尾或轨道末端的）减震器，缓冲器","lab":"British English"},{"en":"an area in a computer’s memory where data can be stored for a short time","cn":"缓存区；缓冲存储区；缓冲器","lab":"computing"},{"en":"an informal way of referring to an old man that shows that you do not respect him","cn":"老家伙；老头儿","lab":"British English, old-fashioned, informal，，，，"},{"en":"to reduce the harmful effects of something","cn":"减少，减缓（伤害）","ex":{"en":"to buffer the effects of stress on health","cn":"减少压力对健康的影响"},"pos":"verb"},{"en":"to protect somebody/yourself from something","cn":"保护；使不受…的侵害","ex":{"en":"They tried to buffer themselves against problems and uncertainties.","cn":"他们尽力保护自己免受困难和不确定因素的影响。"},"pos":"verb"},{"en":"to hold data for a short time before using it","cn":"缓冲存储；缓存","lab":"computing","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"缓冲物","en":"A buffer is something that prevents something else from being harmed or that prevents two things from harming each other.","ex":{"en":"Keep savings as a buffer against unexpected cash needs","cn":"存些积蓄以备不时之需。"}},{"pos":"VERB 动词","cn":"保护；保障","en":"If something is buffered, it is protected from harm.","ex":{"en":"The company is buffered by long-term contracts with growers.","cn":"公司通过与种植户签订长期合同得到保障。"}},{"pos":"N-COUNT 可数名词","cn":"（火车上的）缓冲器；（火车轨道末端的）防撞栅","en":"The buffers on a train or at the end of a railway line are two metal discs on springs that reduce the shock when a train hits them."},{"pos":"N-COUNT 可数名词","cn":"（电脑内存的）缓冲区","en":"A buffer is an area in a computer's memory where information can be stored for a short time."},{"pos":"N-COUNT 可数名词","cn":"老糊涂；蠢老头","en":"If you say that someone, usually a man, is an old buffer, you mean that you think they are rather foolish.","ex":{"en":"...a collection of old buffers who meet at the Grosvenor House once a month for lunch.","cn":"每月一次在格罗夫纳大厦进行午餐聚会的一群蠢老头们"}}]},"media":{"uk":"media/uk/buffer__gb_1.mp3","us":"media/us/buffer__us_1.mp3"},"examples":[{"en":"a buffer state (= a small country between two powerful states that helps keep peace between them)","cn":"缓冲国（两敌对大国之间有助于维持和平的小国家）"},{"en":"They tried to buffer themselves against problems and uncertainties.","cn":"他们尽力保护自己免受困难和不确定因素的影响。"}]},"bust":{"media":{"uk":"media/uk/bust__gb_1.mp3","us":"media/us/bust__us_1.mp3"},"oxford":{"phon":"bʌst","pos":"verb","senses":[{"en":"to break something","cn":"打破；摔碎","ex":{"en":"I bust my camera.","cn":"我把照相机摔坏了。"}},{"en":"to suddenly enter a place and search it or arrest somebody","cn":"突击搜查（或搜捕）","ex":{"en":"He's been busted for drugs.","cn":"他因涉嫌毒品而遭到拘捕。"}},{"en":"to make somebody lower in military rank as a punishment","cn":"（使）降级，降低军阶","lab":"especially North American English"},{"en":"a stone or metal model of a person’s head, shoulders and chest","cn":"（石或金属的）半身像","ex":{"en":"a marble bust of Napoleon","cn":"拿破仑的大理石半身像"},"pos":"noun"},{"en":"(used especially when talking about clothes or measurements) a woman’s breasts or the measurement around the breasts and back","cn":"（尤指衣服或尺寸）女子的胸部，胸围","ex":{"en":"What is your bust measurement, Madam?","cn":"您的胸围是多少，太太？"},"pos":"noun"},{"en":"a period of economic difficulty in which people and businesses struggle to survive","cn":"经济萧条期；经济不景气","ex":{"en":"Will it be boom or bust for the property market?","cn":"房地产市场会繁荣还是萧条？"},"pos":"noun"},{"en":"an unexpected visit made by the police in order to arrest people for doing something illegal","cn":"（警方的）突击搜捕，突击搜查","lab":"informal","ex":{"en":"a drug bust","cn":"突击搜查毒品"},"pos":"noun"},{"en":"a thing that is not good","cn":"蹩脚的东西；没价值的事物","lab":"North American English","ex":{"en":"As a show it was a bust.","cn":"作为一场演出，那可不怎么样。"},"pos":"noun"},{"en":"broken","cn":"破碎；毁坏","lab":"British English","ex":{"en":"My watch is bust.","cn":"我的表坏了。"},"pos":"adjective"},{"en":"failed because of a lack of money","cn":"破产","ex":{"en":"We're bust!","cn":"我们破产了！"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"打碎；破坏","en":"If you bust something, you break it or damage it so badly that it cannot be used.","ex":{"en":"They will have to bust the door to get him out.","cn":"他们将不得不撞破门把他弄出来。"}},{"pos":"VERB 动词","cn":"逮捕；拘留","en":"If someone is busted, the police arrest them.","ex":{"en":"They were busted for possession of cannabis.","cn":"他们因藏有大麻被逮捕。"}},{"pos":"VERB 动词","cn":"（警察）搜查","en":"If police bust a place, they go to it in order to arrest people who are doing something illegal.","ex":{"en":"...police success in busting UK-based drug factories.","cn":"警察对英国的毒品加工厂成功实施的突击搜查"}},{"pos":"ADJ 形容词","cn":"破产的；倒闭的","en":"A company or fund that is bust has no money left and has been forced to close down.","ex":{"en":"It is taxpayers who will pay most of the bill for bailing out bust banks.","cn":"是纳税人将支付大部分的账单以解救面临倒闭的银行。"}},{"pos":"PHRASE 短语","cn":"破产；倒闭","en":"If a company goes bust, it loses so much money that it is forced to close down.","ex":{"en":"...a Swiss company which went bust last May.","cn":"一家去年5月倒闭的瑞士公司"}},{"pos":"N-COUNT 可数名词","cn":"半身像；胸像","en":"A bust is a statue of the head and shoulders of a person.","ex":{"en":"...a bronze bust of the Queen.","cn":"女王的半身铜像"}},{"pos":"N-COUNT 可数名词","cn":"（女人的）胸部","en":"You can use bust to refer to a woman's breasts, especially when you are describing their size.","ex":{"en":"Good posture also helps your bust look bigger.","cn":"优美的姿势也能让你的胸部看起来更丰满。"}},{"pos":"","cn":"","en":"to bust a gut→see: ;"}]},"examples":[{"en":"We lost our money when the travel company went bust.","cn":"旅行社破产，我们的钱都赔了进去。"},{"en":"As a show it was a bust.","cn":"作为一场演出，那可不怎么样。"}]},"burial":{"media":{"uk":"media/uk/burial__gb_1.mp3","us":"media/us/burial__us_1.mp3"},"oxford":{"phon":"ˈberiəl","pos":"noun","senses":[{"en":"the act or ceremony of burying a dead body","cn":"埋葬；葬礼","ex":{"en":"a burial place/mound/site","cn":"安葬地；坟头；坟地"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"葬礼；埋葬","en":"A burial is the act or ceremony of putting a dead body into a grave in the ground.","ex":{"en":"The priest prepared the body for burial","cn":"牧师给死者作安葬准备。"}}]},"examples":[{"en":"His family insisted he should be given a proper burial.","cn":"他的家人坚持应该为他举行适当的葬礼。"},{"en":"Her body was sent home for burial.","cn":"她的尸骨已运回家乡安葬。"}]},"burying":{"lemma":"bury"},"businessman":{"oxford":{"phon":"ˈbɪznəsmæn","pos":"noun","senses":[{"en":"a man who works in business, especially at a high level","cn":"商人：从事商业工作，尤其是高水平工作的人","ex":{"en":"a group of visiting Italian politicians and businessmen","cn":"意大利政商代表团来访"}},{"en":"a man who shows skill in business and financial matters","cn":"商人：在商业和财务事务上表现出技巧的人","ex":{"en":"a successful/wealthy businessman","cn":"成功/富有的商人"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"商人；企业家；实业家","en":"A businessman is a man who works in business."}]},"media":{"uk":"media/ldoce/hwd/bre/c/businessman0205.mp3","us":"media/ldoce/hwd/ame/a/businessman.mp3","img":["media/ldoce/img/businessman.jpg"]}},"buzzing":{"lemma":"buzz"},"burgers":{"lemma":"burger"},"butchers":{"lemma":"butcher"},"bushes":{"lemma":"bush"},"bucks":{"lemma":"buck"},"businesses":{"lemma":"business"},"buying":{"lemma":"buy"},"buttons":{"oxford":{"phon":"ˈbʌtnz","pos":"","senses":[{"en":"a character in the pantomime Cinderella. He is Cinderella's friend, and usually wears a suit with many buttons.","cn":"按钮：灰姑娘中的角色。他是灰姑娘的朋友，通常穿着带有许多纽扣的西装。"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld5_buttons.mp3","us":"media/ldoce/hwd/ame/0/ld5_buttons.mp3"},"base":"button"},"budgets":{"lemma":"budget"},"buildings":{"lemma":"build","media":{"img":["media/pic/buildings_comp.jpg"]}},"buffeted":{"lemma":"buffet"},"busiest":{"lemma":"busy"},"bullied":{"lemma":"bully"},"builds":{"lemma":"build"},"builder":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"建筑工人；建造者","en":"A builder is a person whose job is to build or repair houses and other buildings.","ex":{"en":"The builders have finished the roof.","cn":"建筑工人已经盖好了房顶。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person or a company that builds or repairs buildings","cn":"建筑工人﹔建筑商﹔建造者"}]},"collocations":{"phrases":["ADJ. good, reputable | jobbing, self-employed | local We got a local builder to do the work for us.","VERB + BUILDER be apprenticed to","BUILDER + VERB build sth","PHRASES builder's merchant, builder's yard The house looked like a builder's yard, with stacks of bricks and piles of sand in the garden. • "]},"media":{"uk":"media/ldoce/hwd/bre/a/builder0205.mp3","us":"media/ldoce/hwd/ame/2/builder.mp3"},"examples":[{"en":"a confidence builder","cn":"令人增强信心的事物"},{"en":"a shipbuilder","cn":"造船工人"}],"oxford":{"phon":"ˈbɪldə(r)","pos":"noun","senses":[{"en":"a person or company whose job is to build or repair houses or other buildings","cn":"建筑工人；建筑公司；营造商","ex":{"en":"We got a local builder to do the work for us.","cn":"我们找了一家本地建筑公司为我们做这项工程。"}},{"en":"a person or thing that builds, creates or develops something","cn":"建筑者；创建者；开发者","ex":{"en":"a shipbuilder","cn":"造船工人"}}]}},"buddhism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"佛教","en":"Buddhism is a religion which teaches that the way to end suffering is by overcoming your desires."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a religion of east and central Asia, based on the teaching of Gautama Buddha","cn":"佛教"}]},"collocations":{"phrases":["ADJ. Zen She became interested in Zen Buddhism. • Note at RELIGION (for verbs and phrases)"]},"media":{"uk":"media/ldoce/hwd/bre/2/buddhism0205.mp3","us":"media/ldoce/hwd/ame/c/buddhism.mp3"},"examples":[{"en":"a Buddhist monk/temple","cn":"佛教僧侣/寺庙"},{"en":"a devout Buddhist","cn":"虔诚的佛教徒"}],"oxford":{"phon":"ˈbʊdɪzəm","pos":"noun","senses":[{"en":"an Indian religion widely followed in Asia, based on the teaching of Siddhartha Gautama (or Buddha)","cn":"佛教","ex":{"en":"She became interested in Zen Buddhism.","cn":"她对禅宗佛教产生了兴趣。"}}]}},"bumper":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（汽车前后的）保险杠","en":"Bumpers are bars at the front and back of a vehicle which protect it if it bumps into something.","ex":{"en":"...bumper to bumper traffic jams.","cn":"车挨着车的交通堵塞"}},{"pos":"ADJ 形容词","cn":"丰收的；丰盛的","en":"A bumper crop or harvest is one that is larger than usual.","ex":{"en":"...a bumper crop of rice","cn":"稻米丰收"}},{"pos":"ADJ 形容词","cn":"巨大的；大号的","en":"If you say that something is bumper size, you mean that it is very large.","ex":{"en":"...bumper profits.","cn":"巨额利润"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bar fixed on the front and back of a car to protect it if it hits anything 〔","cn":"汽车的〕保险杠"},{"en":"bumper-to-bumper traffic is very close together and moving slowly 〔","cn":"车辆〕头尾相接的，一辆紧跟一辆的"},{"en":"unusually large","cn":"特大的﹔丰盛的"}]},"collocations":{"phrases":["ADJ. front | back, rear","PHRASES bumper to bumper The cars crawled along bumper to bumper (= very close to each other) ."]},"media":{"uk":"media/ldoce/hwd/bre/9/bumper_adj0205.mp3","us":"media/ldoce/hwd/ame/1/bumper1.mp3"},"examples":[{"en":"The cars were bumper to bumper on the road to the coast (= so close that their bumpers were nearly touching).","cn":"车辆一辆紧接一辆把通往海岸的马路挤得水泄不通。"},{"en":"a bumper sticker (= a sign that people stick on the bumper of their cars with a message on it)","cn":"贴在保险杠上的小标语"}],"oxford":{"phon":"ˈbʌmpə(r)","pos":"noun","senses":[{"en":"a bar fixed to the front and back of a car, etc. to reduce the effect if it hits anything","cn":"（汽车头尾的）保险杠","ex":{"en":"a bumper sticker (= a sign that people stick on the bumper of their cars with a message on it)","cn":"贴在保险杠上的小标语"}},{"en":"unusually large; producing an unusually large amount","cn":"异常大的；丰盛的","ex":{"en":"a bumper issue (= of a magazine, etc.)","cn":"（期刊的）特大号"},"pos":"adjective"}]}},"burrow":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(兔子等动物掘的）洞穴，地洞","en":"A burrow is a tunnel or hole in the ground that is dug by an animal such as a rabbit."},{"pos":"VERB 动词","cn":"钻地道；挖洞","en":"If an animal burrows into the ground or into a surface, it moves through it by making a tunnel or hole.","ex":{"en":"The larvae burrow into cracks in the floor.","cn":"幼虫钻进了地板的缝隙里。"}},{"pos":"VERB 动词","cn":"翻找；搜寻","en":"If you burrow in a container or pile of things, you search there for something using your hands.","ex":{"en":"He burrowed into the pile of charts feverishly.","cn":"他非常紧张地在一堆图表中翻找。"}},{"pos":"VERB 动词","cn":"依偎；紧靠","en":"If you burrow into something, you move underneath it or press against it, usually in order to feel warmer or safer.","ex":{"en":"She turned her face away from him, burrowing into her heap of covers.","cn":"她侧过脸背向他，钻进她那堆被子里。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a hole in the ground using your hands, a tool, or a machine","cn":""},{"en":"to dig a hole in the ground, using your hands or a tool","cn":""},{"en":"if an animal burrows, it makes a hole or a passage in the ground by digging the earth with its feet, nose etc","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Rabbits live in a burrow or a set of tunnels under the earth. They make these tunnels by burrowing , or digging holes with their bodies."}]},"collocations":{"phrases":["ADV. deep | away, down He switched off the bedside lamp and burrowed down beneath the bedclothes.","PREP. beneath/under Rabbits had burrowed under the fence. | into Earthworms burrow deep into the subsoil. | through worms that burrow throug","PHRASES burrow your way Ivy had burrowed its way through the walls."]},"media":{"uk":"media/ldoce/hwd/bre/9/burrow_v0205.mp3","us":"media/ldoce/hwd/ame/7/l2burrow.mp3"},"examples":[{"en":"He was afraid that they would burrow into his past.","cn":"他担心他们会追查他的过去。"},{"en":"She burrowed in the drawer for a pair of socks.","cn":"她在抽屉里翻找一双袜子。"}],"oxford":{"phon":"ˈbʌrəʊ","pos":"verb","senses":[{"en":"to make a hole or a tunnel in the ground by digging","cn":"挖掘（洞或洞穴通道）；挖洞","g":"[intransitive, transitive]","ex":{"en":"Earthworms burrow deep into the soil.","cn":"蚯蚓钻土很深。"}},{"en":"to press yourself close to somebody or under something","cn":"偎依；（使…）钻到（…下面）","g":"[intransitive, transitive]","ex":{"en":"He burrowed down beneath the blankets.","cn":"他钻到毯子下面。"}},{"en":"to search for something under or among things","cn":"（在…下面或里面）搜寻","g":"[intransitive]","ex":{"en":"She burrowed in the drawer for a pair of socks.","cn":"她在抽屉里翻找一双袜子。"}},{"en":"a hole or tunnel in the ground made by animals such as rabbits for them to live in","cn":"（动物的）洞穴，洞穴通道","pos":"noun"}]}},"buyer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"购买者；买主；买方","en":"A buyer is a person who is buying something or who intends to buy it.","ex":{"en":"Car buyers are more interested in safety and reliability than speed.","cn":"购车者们更感兴趣的是汽车的安全性和可靠性，而不是它的速度。"}},{"pos":"N-COUNT 可数名词","cn":"（大商店的）采购员，进货员；买手","en":"A buyer is a person who works for a large store deciding what goods will be bought from manufacturers to be sold in the store.","ex":{"en":"I was a buyer for the women's clothing department.","cn":"我是女装部的进货员。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who buys goods from a particular shop, restaurant, or company","cn":""},{"en":"the people in a shop or town who are buying things","cn":""},{"en":"someone who pays for services or advice from a professional person or organization","cn":""}]},"collocations":{"phrases":["ADJ. potential, prospective | first-time The houses are small and inexpensive, ideal for first-time buyers.","VERB + BUYER have | find, get They quickly found a buyer for their house. | sell sth to","PREP. ~ for Have you got a buyer for your house yet?","PHRASES buyer beware In matters of second-hand cars, your motto should be &lsquo;buyer beware&rsquo; (= the buyer is responsible for checkin"]},"media":{"uk":"media/ldoce/hwd/bre/c/buyer0205.mp3","us":"media/ldoce/hwd/ame/4/buyer.mp3"},"examples":[{"en":"Have you found a buyer for your house?","cn":"你的房子找到买主了吗？"},{"en":"There were several potential buyers.","cn":"有好几个潜在的买家。"}],"oxford":{"phon":"ˈbaɪə(r)","pos":"noun","senses":[{"en":"a person who buys something, especially something expensive","cn":"（尤指贵重物品的）买主，买方","ex":{"en":"Have you found a buyer for your house?","cn":"你的房子找到买主了吗？"}},{"en":"a person whose job is to choose goods that will be sold in a large shop","cn":"采购员","ex":{"en":"She was a fashion buyer for a department store.","cn":"她是一家百货公司的时装采购员。"}}]}},"bun":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小圆面包","en":"Buns are small bread rolls. They are sometimes sweet and may contain dried fruit or spices.","ex":{"en":"...a currant bun.","cn":"掺有葡萄干的小圆面包"}},{"pos":"N-COUNT 可数名词","cn":"（表面覆有糖霜的）小蛋糕","en":"Buns are small sweet cakes. They often have icing on the top."},{"pos":"N-COUNT 可数名词","cn":"圆发髻","en":"If a woman has her hair in a bun, she has fastened it tightly on top of her head or at the back of her head in the shape of a ball."},{"pos":"N-COUNT 可数名词","cn":"屁股","en":"Your buns are your buttocks.","ex":{"en":"I'd pinch his buns and kiss his neck.","cn":"我想掐他的屁股，亲他的脖子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small round sweet cake","cn":"小圆糕点"},{"en":"a small round type of bread","cn":"小圆面包"},{"en":"if a woman has her hair in a bun, she fastens it in a small round shape at the back of her head 〔","cn":"盘在脑后的〕圆发髻"}]},"collocations":{"phrases":["ADJ. fresh | stale | cinnamon, cream, currant, hot cross, iced, sticky | hamburger","VERB + BUN eat, have | bake, make •","ADJ. neat, severe, tight | loose","PREP. in a ~ a woman with her hair in a loose bun","PHRASES pull/draw your hair back in(to) a bun Her black hair was drawn back into a neat bun. | tie your hair (back) in a bun, wear your hair"]},"media":{"img":["media/ldoce/img/cheeseburger.jpg","media/thumb/bun.jpg"],"uk":"media/ldoce/hwd/bre/4/bun0205.mp3","us":"media/ldoce/hwd/ame/3/bun.mp3"},"examples":[{"en":"She wore her hair in a bun.","cn":"她盘了个发髻。"},{"en":"a hamburger bun","cn":"一个用来夹汉堡饼的面包"}],"oxford":{"phon":"bʌn","pos":"noun","senses":[{"en":"a small round sweet cake","cn":"小圆甜蛋糕；小圆甜饼","g":"[countable]","ex":{"en":"an iced bun","cn":"加糖霜的小圆蛋糕"}},{"en":"a small round flat bread roll","cn":"圆面包","g":"[countable]","ex":{"en":"a hamburger bun","cn":"一个用来夹汉堡饼的面包"}},{"en":"long hair that has been twisted into a round shape and is worn on top or at the back of the head","cn":"圆发髻","g":"[countable]","ex":{"en":"She wore her hair in a bun.","cn":"她盘了个发髻。"}},{"en":"the two sides of a person’s bottom","cn":"屁股","g":"[plural]","lab":"slang, especially North American English，，"}]}},"bully":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"恃强凌弱者；恶霸","en":"A bully is someone who uses their strength or power to hurt or frighten other people.","ex":{"en":"I fell victim to the office bully","cn":"我成了这个办公室霸王欺侮的对象。"}},{"pos":"VERB 动词","cn":"欺负；恐吓；欺凌","en":"If someone bullies you, they use their strength or power to hurt or frighten you.","ex":{"en":"I wasn't going to let him bully me","cn":"我可不打算任由他欺负。"}},{"pos":"VERB 动词","cn":"迫使；胁迫","en":"If someone bullies you into something, they make you do it by using force or threats.","ex":{"en":"We think an attempt to bully them into submission would be counterproductive","cn":"我们认为试图迫使他们屈服会适得其反。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is cruel deliberately causes pain or makes people suffer","cn":""},{"en":"so determined to get what you want that you do not care how much you harm other people","cn":""},{"en":"not feeling any pity and not caring about other people or their problems","cn":""}]},"vocab":{"pos":"1 v n 2 adj","senses":[{"en":"You might still have terrifying dreams about the bully who harassed you on the playground in second grade. A bully is someone who intimidates people, usually those who are weaker or smaller."}]},"collocations":{"phrases":["ADJ. big, real Leave him alone, you big bully! He's a real bully! | class, playground, school"]},"media":{"uk":"media/ldoce/hwd/bre/0/bully_v0205.mp3","us":"media/ldoce/hwd/ame/1/bully1.mp3"},"examples":[{"en":"He's got a job in New York? Well, bully for him!","cn":"他在纽约找到了份工作？哼，那没什么了不起！"},{"en":"Bullying is a problem in many schools.","cn":"很多学校都出现学生仗势作恶的问题。"}],"oxford":{"phon":"ˈbʊli","pos":"noun","senses":[{"en":"a person who uses their strength or power to frighten or hurt weaker people","cn":"仗势欺人者；横行霸道者","ex":{"en":"the school bully","cn":"学校里的恶霸学生"}},{"en":"to frighten or hurt a weaker person; to use your strength or power to make somebody do something","cn":"恐吓；伤害；胁迫","ex":{"en":"My son is being bullied at school.","cn":"我儿子在学校里受欺负。"},"pos":"verb"}]}},"bursary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"奖学金；助学金","en":"A bursary is a sum of money which is given to someone to allow them to study in a college or university."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an amount of money given to someone so that they can study at a university or college 〔","cn":"大学的〕助学金"}]},"collocations":{"phrases":["ADJ. sports, travel","VERB + BURSARY award sb, offer sb, provide sb with"]},"media":{"uk":"media/ldoce/hwd/bre/2/bursary0205.mp3","us":"media/ldoce/hwd/ame/3/amelasdebursary.mp3"},"oxford":{"phon":"ˈbɜːsəri","pos":"noun","senses":[{"en":"an amount of money that is given to somebody so that they can study, usually at a college or university","cn":"（通常指大学的）奖学金"}]}},"butcher":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"屠夫；屠户；肉贩子","en":"A butcher is a shopkeeper who cuts up and sells meat. Some butchers also kill animals for meat and make foods such as sausages and meat pies."},{"pos":"N-COUNT 可数名词","cn":"肉铺；肉店","en":"A butcher or a butcher's is a shop where meat is sold."},{"pos":"VERB 动词","cn":"屠宰","en":"To butcher an animal means to kill it and cut it up for meat.","ex":{"en":"Pigs were butchered, hams were hung to dry from the ceiling.","cn":"杀了猪，猪腿挂在天花板上风干。"}},{"pos":"N-COUNT 可数名词","cn":"刽子手；杀人狂","en":"You can refer to someone as a butcher when they have killed a lot of people in a very cruel way, and you want to express your horror and disgust.","ex":{"en":"Klaus Barbie was known in France as the Butcher of Lyon.","cn":"在法国，克劳斯·巴比是臭名昭著的“里昂屠夫”。"}},{"pos":"VERB 动词","cn":"屠戮；残杀","en":"You can say that someone has butchered people when they have killed a lot of people in a very cruel way, and you want to express your horror and disgust.","ex":{"en":"Guards butchered 1,350 prisoners","cn":"卫兵们杀掉了1,350名囚犯。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a large shop that sells a wide range of things, especially food, cleaning materials, and other things that people buy regularly","cn":""},{"en":"a shop in your local area that sells food, alcohol, magazines etc and is often open 24 hours a day","cn":""},{"en":"a small local shop, usually on the corner of a street, that sells food, newspapers, cigarettes etc","cn":""}]},"collocations":{"phrases":["ADJ. local | halal, kosher | master • Note at JOB"]},"media":{"img":["media/ldoce/img/butcher.jpg"],"uk":"media/ldoce/hwd/bre/8/butcher_v0205.mp3","us":"media/ldoce/hwd/ame/0/butcher1.mp3"},"examples":[{"en":"The script was good, but those guys butchered it.","cn":"剧本很好，但让那帮家伙给演砸了。"},{"en":"He owns the butcher's in the main street.","cn":"他在大街上开了一家肉铺。"}],"oxford":{"phon":"ˈbʊtʃə(r)","pos":"noun","senses":[{"en":"a person whose job is cutting up and selling meat in a shop or killing animals for this purpose","cn":"屠夫；肉贩"},{"en":"a shop that sells meat","cn":"肉店；肉铺","ex":{"en":"He owns the butcher's in the main street.","cn":"他在大街上开了一家肉铺。"}},{"en":"a person who kills people in a cruel and violent way","cn":"刽子手"},{"en":"to kill people in a very cruel and violent way","cn":"屠杀；杀戮","pos":"verb"},{"en":"to kill animals and cut them up for use as meat","cn":"屠宰；宰杀","pos":"verb"},{"en":"to make something less good or successful by doing it very badly","cn":"搞砸；弄糟","lab":"especially North American English","ex":{"en":"The script was good, but those guys butchered it.","cn":"剧本很好，但让那帮家伙给演砸了。"},"pos":"verb"}]}},"bureaucrat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"官僚；官僚主义者","en":"Bureaucrats are officials who work in a large administrative system. You can refer to officials as bureaucrats especially if you disapprove of them because they seem to follow rules and procedures too strictly.","ex":{"en":"The economy is still controlled by bureaucrats.","cn":"经济依然被官僚们所掌控。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who works in a bureaucracy and uses official rules very strictly","cn":"官僚﹔官僚主义者﹔官僚作风的人"}]},"vocab":{"pos":"n","senses":[{"en":"A bureaucrat is an administrative official who works for the government. You brought the budget office bureaucrat a book about literacy, hoping to convince him you need more funding for the library."}]},"collocations":{"phrases":["ADJ. faceless He was just another faceless bureaucrat. | unelected | high-ranking, senior | career battles between political appointees and "]},"media":{"uk":"media/ldoce/hwd/bre/0/bureaucrat0205.mp3","us":"media/ldoce/hwd/ame/b/bureaucrat.mp3"},"oxford":{"phon":"ˈbjʊərəkræt","pos":"noun","senses":[{"en":"an official working in an organization or a government department, especially one who follows the rules of the department too strictly","cn":"官僚主义者；官僚","ex":{"en":"He was just another faceless bureaucrat.","cn":"他无非是一个毫无个性的官僚。"}}]}},"bureaucracy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"官僚制度","en":"A bureaucracy is an administrative system operated by a large number of officials.","ex":{"en":"State bureaucracies can tend to stifle enterprise and initiative.","cn":"国家的官僚体制往往会扼杀人们的事业心和积极性。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"官僚作风；官僚主义","en":"Bureaucracy refers to all the rules and procedures followed by government departments and similar organizations, especially when you think that these are complicated and cause long delays.","ex":{"en":"People usually complain about having to deal with too much bureaucracy.","cn":"人们经常抱怨不得不应付太多的繁文缛节。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a complicated, official system in which there are a lot of rules and processes that you have to complete, especially one that employs a lot of people","cn":""},{"en":"involving a lot of complicated official rules and processes","cn":""},{"en":"complicated and annoying official rules that you have to obey before you can do or have something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A bureaucracy is an organization made up of many departments and divisions that are administered by lots of people. If you've ever had to deal with health insurance or financial aid, you're familiar with the dark side of bureaucracy ."}]},"collocations":{"phrases":["ADJ. vast | government, state 2 official rules and procedures","ADJ. cumbersome, excessive, unnecessary","VERB + BUREAUCRACY cut out, eliminate, reduce The organization has promised to eliminate cumbersome and unnecessary bureaucracy. | increase"]},"media":{"uk":"media/ldoce/hwd/bre/3/bureaucracy0205.mp3","us":"media/ldoce/hwd/ame/d/bureaucracy.mp3"},"examples":[{"en":"the power of the state bureaucracy","cn":"国家官僚体制的权力"},{"en":"unnecessary/excessive bureaucracy","cn":"不必要的官僚式繁文缛节；过分的官僚作风"}],"oxford":{"phon":"bjʊəˈrɒkrəsi","pos":"noun","senses":[{"en":"the system of official rules and ways of doing things that a government or an organization has, especially when these seem to be too complicated","cn":"官僚主义；官僚作风","g":"[uncountable]","lab":"often disapproving","ex":{"en":"unnecessary/excessive bureaucracy","cn":"不必要的官僚式繁文缛节；过分的官僚作风"}},{"en":"a system of government in which there are a large number of state officials who are not elected; a country with such a system","cn":"官僚体制；实行官僚体制的国家","g":"[uncountable, countable]","ex":{"en":"the power of the state bureaucracy","cn":"国家官僚体制的权力"}}]}},"bulk":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（大）体积；（大）量","en":"You can refer to something's bulk when you want to emphasize that it is very large.","ex":{"en":"The truck pulled out of the lot, its bulk unnerving against the dawn.","cn":"卡车从空地上开出来，庞大的车身小心翼翼地避让着草坪。"}},{"pos":"N-SING 单数名词","cn":"庞大的身躯；巨大的体重；肥硕的体形","en":"You can refer to a large person's body or to their weight or size as their bulk .","ex":{"en":"Bannol lowered his bulk carefully into the chair","cn":"班诺尔小心翼翼地将肥硕的身躯落座到椅子上。"}},{"pos":"QUANT 数量词","cn":"主体；大部分","en":"The bulk of something is most of it.","ex":{"en":"The bulk of the text is essentially a review of these original documents","cn":"文章的主要部分基本是对这些原始文件的回顾。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"大宗，大批（买卖）","en":"If you buy or sell something in bulk, you buy or sell it in large quantities.","ex":{"en":"Buying in bulk is more economical than shopping for small quantities.","cn":"批量采购要比零买实惠很多。"}},{"pos":"","cn":"","en":"相关词组：bulk up"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"how big someone or something is","cn":""},{"en":"the length, width, and height of an object, room, building etc","cn":""},{"en":"the length, width, or height of something, or of someone’s body","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Don’t be intimidated by the bulk of the dictionary on your desk. If you look in it, you’ll see that bulk is a small word used to talk about large things."}]},"collocations":{"phrases":["ADJ. considerable, formidable, huge, massive, sheer I was amazed by the sheer bulk of the creature. | dark, looming, solid","VERB + BULK ease, heave, shift (used about people) He heaved his considerable bulk into the chair. 2 large amount","ADJ. great, large, overwhelming, vast","BULK + NOUN buying, order, purchasing","PREP. in ~ Sugar is imported in bulk from the mainland.","PHRASES the bulk of (= most of) The great bulk of the work has now been done. | buy in bulk It's usually cheaper to buy in bulk."]},"media":{"uk":"media/ldoce/hwd/bre/0/bulk_adj0205.mp3","us":"media/ldoce/hwd/ame/e/bulk1.mp3"},"examples":[{"en":"She heaved her bulk out of the chair.","cn":"她挪动庞大的躯体，费力地从椅子里站起来。"},{"en":"Despite its bulk and weight, the car is extremely fast.","cn":"尽管这辆车大而且重，速度却非常快。"}],"oxford":{"phon":"bʌlk","pos":"noun","senses":[{"en":"the main part of something; most of something","cn":"主体；大部分","g":"[singular]","ex":{"en":"The bulk of the population lives in cities.","cn":"大多数人口居住在城市里。"}},{"en":"the (large) size or quantity of something","cn":"（大）体积；大（量）","g":"[uncountable]","ex":{"en":"Despite its bulk and weight, the car is extremely fast.","cn":"尽管这辆车大而且重，速度却非常快。"}},{"en":"the weight or shape of somebody/something large","cn":"巨大的体重（或重量、形状、身体等）","g":"[singular]","ex":{"en":"She heaved her bulk out of the chair.","cn":"她挪动庞大的躯体，费力地从椅子里站起来。"}}]}},"bungalow":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"平房","en":"A bungalow is a house which has only one level, and no stairs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building that someone lives in, especially one that is intended for one family, person, or couple to live in","cn":""},{"en":"a house that is not joined to another house","cn":""},{"en":"a house that is joined to another house on one side","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A bungalow is a little house. If you’re not ready for the three-story house in the suburbs just yet, you might try living in a bungalow ."}]},"collocations":{"phrases":["ADJ. two-bedroom/two-bedroomed, etc. | detached, semi-detached | suburban | ranch-type | modern | holiday, retirement"]},"media":{"img":["media/ldoce/img/bungalow.jpg","media/thumb/bungalow.jpg"],"uk":"media/ldoce/hwd/bre/6/bungalow0205.mp3","us":"media/ldoce/hwd/ame/b/bungalow.mp3"},"oxford":{"phon":"ˈbʌŋɡələʊ","pos":"noun","senses":[{"en":"a house built all on one level, without stairs","cn":"平房","lab":"British English","ex":{"en":"He retired at 70 and moved to a bungalow in Rosecroft Gardens.","cn":"他70岁退休，之后搬到了罗斯克罗夫特花园街的一处平房居住。"}},{"en":"(in South-East Asia) a large house, sometimes on more than one level, that is not joined to another house on either side","cn":"（某些亚洲国家的）平房，独座房屋"}]}},"buzzer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蜂鸣器","en":"A buzzer is an electrical device that is used to make a buzzing sound for example, to attract someone's attention.","ex":{"en":"She rang a buzzer at the information desk.","cn":"她按了一下服务台的蜂鸣器。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small thing, usually shaped like a button, that buzz es when you press it","cn":"蜂鸣器"}]},"collocations":{"phrases":["VERB + BUZZER press, sound Press the buzzer when you want to talk.","BUZZER + VERB go (off), sound The buzzer went off at eight o'clock."]},"media":{"uk":"media/ldoce/hwd/bre/1/buzzer0205.mp3","us":"media/ldoce/hwd/ame/4/buzzer.mp3"},"examples":[{"en":"He missed a three-point attempt at the buzzer.","cn":"终场哨响时，他投三分球未中。"},{"en":"Press the buzzer if you know the answer.","cn":"如果你知道答案﹐就按抢答器。"}],"oxford":{"phon":"ˈbʌzə(r)","pos":"noun","senses":[{"en":"an electrical device that produces a buzzing sound as a signal","cn":"蜂鸣器","ex":{"en":"Put your fingers on the buzzer and be ready to answer.","cn":"将手指放在蜂鸣器上，准备接听。"}}]}},"bureaucratic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"官僚式的；官僚主义的","en":"Bureaucratic means involving complicated rules and procedures which can cause long delays.","ex":{"en":"Diplomats believe that bureaucratic delays are inevitable","cn":"外交官们认为繁文缛节造成的延迟是在所难免的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a complicated, official system in which there are a lot of rules and processes that you have to complete, especially one that employs a lot of people","cn":""},{"en":"involving a lot of complicated official rules and processes","cn":"官僚式的﹔官僚主义的"},{"en":"complicated and annoying official rules that you have to obey before you can do or have something","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Anything bureaucratic has to do with the business of running an organization — usually not in a very efficient manner."}]},"collocations":{"phrases":["VERBS be | become","ADV. extremely, highly, very The organization is highly bureaucratic. | rather, somewhat | unnecessarily"]},"media":{"uk":"media/ldoce/hwd/bre/d/bureaucratic0205.mp3","us":"media/ldoce/hwd/ame/c/bureaucratic.mp3"},"examples":[{"en":"The report revealed a great deal of bureaucratic inefficiency.","cn":"报道大量揭示了官僚体制的无能。"},{"en":"bureaucratic power/control/procedures/organizations","cn":"官僚权力/管理/程序/组织"}],"oxford":{"phon":"ˌbjʊərəˈkrætɪk","pos":"adjective","senses":[{"en":"connected with a bureaucracy or bureaucrats and involving complicated official rules which may seem unnecessary","cn":"官僚的；官僚主义的","ex":{"en":"bureaucratic power/control/procedures/organizations","cn":"官僚权力／管理／程序／组织"}}]}},"buttock":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"屁股；臀部","en":"Your buttocks are the two rounded fleshy parts of your body that you sit on."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of the fleshy parts of your body that you sit on","cn":"屁股﹐臀部"}]},"collocations":{"phrases":["ADJ. firm | plump, rounded | scrawny"]},"media":{"uk":"media/ldoce/hwd/bre/e/buttock0205.mp3","us":"media/ldoce/hwd/ame/3/buttock.mp3"},"oxford":{"phon":"ˈbʌtək","pos":"noun","senses":[{"en":"either of the two round soft parts at the top of a person’s legs","cn":"屁股的一边；臀部","ex":{"en":"He fell down hard on his right buttock and slid along the path.","cn":"他狠狠地摔到了右边屁股，顺着小路滑了出去。"}}]}},"buggy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同baby buggy","en":"A buggy is the same as a baby buggy ."},{"pos":"N-COUNT 可数名词","cn":"（一匹马拉的）轻便马车","en":"A buggy is a small lightweight carriage pulled by one horse."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a light folding chair on wheels that you push small children in","cn":"折叠式婴儿推车"},{"en":"a light carriage pulled by a horse 〔","cn":"一匹马拉的〕轻型马车"},{"en":"a small bed on wheels, that a baby lies in 〔","cn":"婴儿可躺卧的〕婴儿车"}]},"collocations":{"phrases":["ADJ. baby | beach, golf","VERB + BUGGY push parents pushing baby buggies"]},"media":{"uk":"media/ldoce/hwd/bre/2/buggy0205.mp3","us":"media/ldoce/hwd/ame/8/buggy.mp3"},"examples":[{"en":"a garden/golf buggy","cn":"花园/高尔夫球场小汽车"}],"oxford":{"phon":"ˈbʌɡi","pos":"noun","senses":[{"en":"a small car, often without a roof or doors, used for a particular purpose","cn":"（常指无顶无门的）专用小汽车","lab":"British English","ex":{"en":"a garden/golf buggy","cn":"花园／高尔夫球场小汽车"}},{"en":"a type of light folding chair on wheels in which a baby or small child is pushed along","cn":"婴儿车；童车","lab":"British English also","ex":{"en":"parents pushing baby buggies","cn":"推着婴儿车的父母"}},{"en":"a light carriage for one or two people, pulled by one horse","cn":"（由一匹马拉的单座或双座）轻便马车","ex":{"en":"a horse-drawn buggy","cn":"马车"}},{"en":"full of bugs so it does not work correctly","cn":"有很多漏洞的","ex":{"en":"The software is buggy and slow.","cn":"这个软件有很多漏洞，运行很慢。"},"pos":"adjective"},{"en":"full of bugs (= insects)","cn":"有很多昆虫的","ex":{"en":"The summers are hot and humid and buggy.","cn":"夏天闷热潮湿，有很多小虫。"},"pos":"adjective"},{"en":"crazy","cn":"精神失常的；发疯的","lab":"North American English","ex":{"en":"With this app, kids go buggy over math.","cn":"这款应用软件令孩子们对数学着迷。"},"pos":"adjective"},{"en":"sticking out, especially in a way that looks crazy","cn":"凸出来的","lab":"North American English","ex":{"en":"I do not believe in little alien dudes with buggy eyes.","cn":"我不相信真有那些凸眼睛的小外星人。"},"pos":"adjective"}]}},"bud":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"芽；苞；花蕾","en":"A bud is a small pointed lump that appears on a tree or plant and develops into a leaf or flower.","ex":{"en":"Rosanna's favourite time is early summer, just before the buds open.","cn":"罗莎娜最喜爱的季节是初夏，恰在花蕾绽放前。"}},{"pos":"VERB 动词","cn":"发芽；萌芽","en":"When a tree or plant is budding, buds are appearing on it or are beginning to open.","ex":{"en":"The leaves were budding on the trees below.","cn":"下面的树正在发芽。"}},{"pos":"N-VOC 称呼名词","cn":"老友；伙计；老兄","en":"Some men use bud as a way of addressing other men.","ex":{"en":"You heard what the boss said, bud.","cn":"你听见老板说的话了，老兄。"}},{"pos":"PHRASE 短语","cn":"在发芽；长出花苞","en":"When a tree or plant is in bud or has come into bud, it has buds on it.","ex":{"en":"The flowers are bronzy in bud and bright yellow when open.","cn":"这些花的花蕾是青铜色，开放后呈明黄色。"}},{"pos":"PHRASE 短语","cn":"把…消灭在萌芽状态；防（患）于未然","en":"If you nip something such as bad behaviour in the bud, you stop it before it can develop very far.","ex":{"en":"It is important to recognize jealousy and to nip it in the bud before it gets out of hand.","cn":"重要的是要甄辨出嫉妒情绪并尽早消除这种心理，以免其一发不可收拾。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to stop a bad situation or bad behaviour when it first starts, before it can develop further","cn":""},{"en":"to quickly stop something such as opposition to your plans that is likely to cause you trouble","cn":""},{"en":"to stop something quickly and completely","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"The young part of a plant that's almost ready to flower or unfurl new leaves is called the bud . As a verb bud also means to grow or develop."}]},"collocations":{"phrases":["ADJ. flower, leaf","VERB + BUD be in, come into The roses are in bud.","BUD + VERB burst, open"]},"media":{"uk":"media/ldoce/hwd/bre/8/bud_n0205.mp3","us":"media/ldoce/hwd/ame/8/bud1.mp3"},"examples":[{"en":"Listen, bud, enough of the wisecracks, OK?","cn":"听着，老兄，别再说俏皮话了行不行？"},{"en":"The tree is in bud already.","cn":"树已长出花蕾。"}],"oxford":{"phon":"bʌd","pos":"noun","senses":[{"en":"a small closed part that grows on a plant and from which a flower, leaf or stem develops; a flower or leaf that is not fully open","cn":"芽；苞；花蕾","ex":{"en":"the first buds appearing in spring","cn":"春天的初芽"}},{"en":"used to speak to a man you do not know","cn":"（称呼不认识的男子）老兄，喂","lab":"North American English, informal，，","ex":{"en":"Listen, bud, enough of the wisecracks, OK?","cn":"听着，老兄，别再说俏皮话了行不行？"}},{"en":"to produce buds","cn":"发芽","ex":{"en":"The tree is already budding.","cn":"树已发芽。"},"pos":"verb"},{"en":"a first name for boys","cn":"巴德（男子名）","pos":""}]}},"businesslike":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"麻利的；务实的；效率高的","en":"If you describe someone as businesslike, you mean that they deal with things in an efficient way without wasting time.","ex":{"en":"Mr. Penn sounds quite businesslike","cn":"佩恩先生听起来是个非常务实的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is efficient works well and does what needs to be done without wasting time","cn":""},{"en":"an efficient way of working","cn":""},{"en":"someone who is effective , especially someone in a position of authority, deals quickly and successfully with the work they have to do","cn":""}]},"collocations":{"phrases":["VERBS be, sound | become | remain | keep sth I'd rather keep the relationship strictly businesslike.","ADV. very a very businesslike manner | strictly | quite"]},"media":{"uk":"media/ldoce/hwd/bre/0/businesslike0205.mp3","us":"media/ldoce/hwd/ame/1/businesslike.mp3"},"examples":[{"en":"She adopted a brisk businesslike tone.","cn":"她用一种公务口吻，说话干脆利落。"},{"en":"a businesslike manner","cn":"务实的态度"}],"oxford":{"phon":"ˈbɪznəslaɪk","pos":"adjective","senses":[{"en":"working in an efficient and organized way and not wasting time or thinking about personal things","cn":"效率高的；井然有序的；工作认真而有条理的","ex":{"en":"She adopted a brisk businesslike tone.","cn":"她用一种公务口吻，说话干脆利落。"}}]}},"budge":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）改变主意；（使）让步","en":"If someone will not budge on a matter, or if nothing budges them, they refuse to change their mind or to come to an agreement.","ex":{"en":"Both sides say they will not budge","cn":"双方都声称决不让步。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）移动；挪动","en":"If someone or something will not budge, they will not move. If you cannot budge them, you cannot make them move.","ex":{"en":"Her mother refused to budge from London","cn":"她母亲不肯离开伦敦。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go to a different place, or change the position of your body","cn":""},{"en":"to move slowly from one side to the other","cn":""},{"en":"to move repeatedly from one side to another, with small gentle movements","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To budge is to move — but just a little bit. People can budge physically from where they're sitting or standing, and people can budge from opinions and positions too."}]},"collocations":{"phrases":["VERB + BUDGE refuse to, will/would not","PREP. from He refuses to budge from his principles. | on The union won't budge on its demand.","PHRASES not budge an inch He threw all his weight against the door, but it wouldn't budge an inch."]},"media":{"uk":"media/ldoce/hwd/bre/a/budge0205.mp3","us":"media/ldoce/hwd/ame/3/budge.mp3"},"examples":[{"en":"She pushed at the door but it wouldn't budge.","cn":"她推了推门，门却一动不动。"},{"en":"He won't budge an inch on the issue.","cn":"在这一点上他丝毫不肯让步。"}],"oxford":{"phon":"bʌdʒ","pos":"verb","senses":[{"en":"to move slightly; to make something/somebody move slightly","cn":"（使）轻微移动，挪动","g":"[intransitive, transitive]","ex":{"en":"She pushed at the door but it wouldn't budge.","cn":"她推了推门，但门纹丝不动。"}},{"en":"to change your opinion about something; to make somebody change their opinion","cn":"（使）改变主意，改变观点","g":"[intransitive, transitive, often passive]","ex":{"en":"He won't budge an inch on the issue.","cn":"在这一点上他丝毫不肯让步。"}}]}},"burglary":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"入室盗窃（罪）","en":"If someone commits a burglary, they enter a building by force and steal things. Burglary is the act of doing this.","ex":{"en":"An 11-year-old boy committed a burglary","cn":"一个11岁的小男孩犯了入室盗窃罪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of stealing from a bank, shop etc","cn":""},{"en":"the crime of breaking into someone’s home in order to steal things","cn":""},{"en":"the crime of stealing something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A burglary is committed when a person breaks into a building with the intent of committing a crime, especially if the crime is to steal valuable items."}]},"collocations":{"phrases":["ADJ. attempted | aggravated (law) (= burglary involving further violence or unpleasant behaviour) | house","BURGLARY + VERB happen, take place","PREP. ~ at Audio equipment was stolen in a burglary at a house in Main Road. • Note at CRIME (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/3/burglary0205.mp3","us":"media/ldoce/hwd/ame/2/burglary.mp3"},"examples":[{"en":"The youth was charged with three counts of burglary.","cn":"那个年轻人被控犯有三次入室盗窃罪。"},{"en":"a rise in the number of burglaries committed in the area","cn":"该地区盗窃案例数目的上升"}],"oxford":{"phon":"ˈbɜːɡləri","pos":"noun","senses":[{"en":"the crime of entering a building illegally and stealing things from it","cn":"入室偷盗罪","ex":{"en":"The youth was charged with three counts of burglary.","cn":"那个年轻人被控犯有三次入室盗窃罪。"}}]}},"burglar":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"破门盗窃者；窃贼","en":"A burglar is a thief who enters a house or other building by force. →see usage note at:","ex":{"en":"Burglars broke into their home.","cn":"窃贼闯进了他们家。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who steals things from a person or place","cn":""},{"en":"someone who goes into houses, offices etc to steal things","cn":""},{"en":"someone who steals from banks, offices, houses etc, especially using threats or violence","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Use the word burglar when you're talking about someone who steals things from inside a house or a building."}]},"collocations":{"phrases":["ADJ. professional | cat (= a burglar who climbs up the outside of buildings) | suspected","VERB + BURGLAR hunt (informal) Police are hunting burglars who stole property worth &pound; 3,500. | catch","BURGLAR + VERB break in The burglar had broken in through a window. | steal sth | strike Burglars had already struck twice that week in thei","BURGLAR + NOUN alarm"]},"media":{"uk":"media/ldoce/hwd/bre/d/ld44burglar.mp3","us":"media/ldoce/hwd/ame/e/burglar.mp3"},"oxford":{"phon":"ˈbɜːɡlə(r)","pos":"noun","senses":[{"en":"a person who enters a building illegally in order to steal","cn":"破门盗贼；入室窃贼","ex":{"en":"Burglars broke into the gallery and stole dozens of priceless paintings.","cn":"窃贼破门进入美术馆，偷走了很多幅极珍贵的画作。"}}]}},"bum":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"屁股；臀部","en":"Someone's bum is the part of their body which they sit on."},{"pos":"N-COUNT 可数名词","cn":"乞丐；无业游民","en":"A bum is a person who has no permanent home or job and who gets money by working occasionally or by asking people for money."},{"pos":"N-COUNT 可数名词","cn":"无赖；废物；瘪三","en":"If someone refers to another person as a bum, they think that person is worthless or irresponsible.","ex":{"en":"You're all a bunch of bums.","cn":"你们都是一群废物。"}},{"pos":"ADJ 形容词","cn":"糟糕的；令人不快的","en":"Some people use bum to describe a situation that they find unpleasant or annoying.","ex":{"en":"He knows you're getting a bum deal.","cn":"他知道你在做一笔烂生意。"}},{"pos":"VERB 动词","cn":"讨要；提出要","en":"If you bum something off someone, you ask them for it and they give it to you.","ex":{"en":"Mind if I bum a cigarette?","cn":"能给我一支烟吗？"}},{"pos":"VERB 动词","cn":"闲逛；游荡","en":"If you bum around, you go from place to place without any particular destination, either for enjoyment or because you have nothing else to do.","ex":{"en":"I think they're just bumming around at the moment, not doing a lot","cn":"我想他们目前只是在四处闲逛，没做多少事。"}},{"pos":"PHRASE 短语","cn":"招揽观众","en":"If the organizers of an event such as a concert want to put bums on seats, they want a lot of people to attend it.","ex":{"en":"He is one of the few players who puts bums on seats.","cn":"他是少数几个知道招揽观众的演员之一。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has no home or regular work","cn":""},{"en":"a person, usually a man, who has no home or regular job and asks people for money on the streets","cn":""},{"en":"a woman with no home or job who carries all her possessions around with her in a bag","cn":""}]},"vocab":{"pos":"1 n v adj 2 n","senses":[{"en":"Your bum is your bottom, your rear-end, your behind. It can also be a vagrant or hobo, as well as a verb for lazing ( bumming ) around."}]},"collocations":{"phrases":["VERB + BUM feel, pinch A man pinched her bum on the train so she hit him. | sit on They've been sitting on their bums all day, doing nothing","ADJ. low-down, no-good | lazy | beach He dropped out of college and became a beach bum."]},"media":{"uk":"media/ldoce/hwd/bre/0/bum_v0205.mp3","us":"media/ldoce/hwd/ame/7/bum1.mp3"},"examples":[{"en":"They're not bothered about attracting the right audience — they just want bums on seats.","cn":"他们不在乎观众是什么样的人，只求卖座。"},{"en":"He was soon given the bum's rush from the club.","cn":"他很快从俱乐部里被撵了出来。"}],"oxford":{"phon":"bʌm","pos":"noun","senses":[{"en":"the part of the body that you sit on","cn":"屁股","lab":"British English","ex":{"en":"They've been sitting on their bums all day, doing nothing.","cn":"他们一整天就那么坐着，什么事都没做。"}},{"en":"a person who has no home or job and who asks other people for money or food","cn":"流浪乞丐；无业游民","lab":"especially North American English","ex":{"en":"a beach bum (= somebody who spends all their time on the beach, without having a job)","cn":"海滨流浪汉"}},{"en":"a lazy person who does nothing for other people or for society","cn":"懒汉；游手好闲者","ex":{"en":"He's nothing but a no-good bum!","cn":"他不过是个没用的懒汉！"}},{"en":"to get something from somebody by asking","cn":"提出要；乞讨","lab":"informal","ex":{"en":"He bummed a ride home from a friend.","cn":"他搭朋友的车回家。"},"pos":"verb"},{"en":"to make somebody feel upset or disappointed","cn":"使不安；使灰心","lab":"North American English, informal，，","pos":"verb"},{"en":"of bad quality; wrong or not worth anything","cn":"质量差的；错误的；无价值的","ex":{"en":"He didn't play one bum note.","cn":"他一个音也没奏错。"},"pos":"adjective"}]}},"bull":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公牛","en":"A bull is a male animal of the cow family."},{"pos":"N-COUNT 可数名词","cn":"雄兽；雄性动物","en":"Some other male animals, including elephants and whales, are called bulls .","ex":{"en":"...a massive bull elephant with huge tusks.","cn":"一头体形庞大、长着巨大象牙的雄象"}},{"pos":"N-COUNT 可数名词","cn":"（预期股价上涨而买进股票以期不久可高价卖出获利的）买空者，多头","en":"On the stock market, bulls are people who buy shares in expectation of a price rise, in order to make a profit by selling the shares again after a short time."},{"pos":"N-COUNT 可数名词","cn":"教皇诏书；教皇训谕","en":"In the Roman Catholic church, a papal bull is an official statement on a particular subject that is issued by the Pope."},{"pos":"N-UNCOUNT 不可数名词","cn":"胡说；废话","en":"If you say that something is bull or a load of bull, you mean that it is complete nonsense or absolutely untrue.","ex":{"en":"I think it's a load of bull","cn":"我认为那是胡说八道。"}},{"pos":"PHRASE 短语","cn":"像闯进瓷器店的公牛一样；莽撞冒失","en":"If you say that someone rushes into a situation like a bull in a china shop, you are critical of them because they do not stop to think, and are insensitive to other people's feelings.","ex":{"en":"Still, it'll stop him rampaging all over the place like a bull in a china shop.","cn":"尽管如此，这将会让他不再像个冒失鬼一样到处横冲直撞了。"}},{"pos":"PHRASE 短语","cn":"好像公牛进了瓷器店；笨手笨脚","en":"You say that someone is like a bull in a china shop when they are very clumsy."},{"pos":"PHRASE 短语","cn":"勇敢面对危险（或困境）","en":"If you take the bull by the horns, you do something that you feel you ought to do even though it is difficult, dangerous, or unpleasant.","ex":{"en":"Now is the time for the Chancellor to take the bull by the horns and announce a two per cent cut in interest rates.","cn":"现在是财政大臣迎难而上，宣布利率下调两个百分点的时候了。"}},{"pos":"","cn":"","en":"like a red rag to a bull→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to make someone fairly angry","cn":""},{"en":"to keep annoying someone","cn":""},{"en":"an impolite expression meaning to annoy someone","cn":""}]},"media":{"img":["media/ldoce/img/bull.jpg"],"uk":"media/ldoce/hwd/bre/a/brelasdebull.mp3","us":"media/ldoce/hwd/ame/1/bull1.mp3"},"examples":[{"en":"a bull neck (= a short thick neck like a bull's ) （","cn":"公牛般的）短粗脖子"},{"en":"That's a load of bull!","cn":"那是胡说八道！"}],"oxford":{"phon":"bʊl","pos":"noun","senses":[{"en":"the male of any animal in the cow family","cn":"公牛","g":"[countable]","ex":{"en":"a bull neck (= a short thick neck like a bull's)","cn":"（公牛般的）短粗脖子"}},{"en":"the male of the elephant, whale and some other large animals","cn":"雄的（象、鲸等）大动物","g":"[countable]","ex":{"en":"a bull elephant","cn":"公象"}},{"en":"a person who buys shares in a company, hoping to sell them soon afterwards at a higher price","cn":"（预期证券价格上升的）买空者，多头","g":"[countable]","lab":"finance"},{"en":"an official order or statement from the Pope (= the head of the Roman Catholic Church)","cn":"教皇诏书；教皇训谕","g":"[countable]","ex":{"en":"a papal bull","cn":"教皇训谕"}},{"en":"ideas, statements or beliefs that you think are silly or not true","cn":"胡说；胡扯","g":"[uncountable]","lab":"informal","ex":{"en":"That's a load of bull!","cn":"那是胡说八道！"}},{"en":"the centre of the target that you shoot or throw at in shooting, archery or darts; a shot or throw that hits this","cn":"靶心；鹄的；命中靶心","g":"[countable]"}]}}});
